  "filePath": "src/index.ts",
  "content": "1 | /**
2 |  * 主入口文件
3 |  * 初始化并启动 AI Agent 应用
4 |  */
5 | import dotenv from 'dotenv';
6 | import { OpenAIProvider } from './providers/openai';
7 | import Agent from './agent';
8 | import { CLI } from './cli';
9 | import { registerDefaultToolsAsync, ToolRegistry } from './tool';
10 | import { operatorPrompt } from './prompts/operator';
11 | import { setAgentContext } from './context';
12 | 
13 | const env = process.env.NODE_ENV || 'development';
14 | dotenv.config({ path: `.env.${env}`, override: true });
15 | 
16 | /**
17 |  * 应用配置
18 |  */
19 | interface AppConfig {
20 |     deepseekApiKey: string;
21 |     deepseekBaseUrl: string;
22 | }
23 | 
24 | /**
25 |  * 初始化应用
26 |  */
27 | async function initializeApp(config: AppConfig) {
28 |     // 初始化工具（包括 MCP 工具）
29 |     await registerDefaultToolsAsync();
30 | 
31 |     // 初始化 LLM Provider
32 |     const llmProvider = new OpenAIProvider({
33 |         apiKey: config.deepseekApiKey,
34 |         baseURL: config.deepseekBaseUrl,
35 |     });
36 | 
37 |     const customPrompt = operatorPrompt({
38 |         directory: process.cwd(),
39 |         vcs: "git",
40 |         language: "Chinese",
41 |     });
42 | 
43 |     console.log(`Available tools:\n${ToolRegistry.getSchemas().map(tool => `'${tool.function.name}'`).join("\n")}`);
44 | 
45 |     // 创建 Agent（内部会创建 AgentContext）
46 |     const agent = new Agent({
47 |         llmProvider,
48 |         systemPrompt: customPrompt,
49 |         defaultTools: ToolRegistry.getSchemas(),
50 |     });
51 | 
52 |     // 设置全局 AgentContext 单例（供 ToolRegistry 等使用）
53 |     setAgentContext(agent.context);
54 | 
55 |     agent.start();
56 | 
57 |     console.log(`[App] Initialized with session: ${agent.context.sessionId}`);
58 |     console.log(`[App] Cache directory: ${agent.context.cacheRoot}`);
59 |     console.log(`[App] Session directory: ${agent.context.sessionDir}`);
60 | 
61 |     return { agent, sessionId: agent.context.sessionId };
62 | }
63 | 
64 | /**
65 |  * 启动 CLI 交互模式
66 |  */
67 | async function startCLI(agent: Agent, sessionId: string): Promise<void> {
68 |     const cli = new CLI({
69 |         agent,
70 |         sessionId,
71 |         prompt: '>',
72 |     });
73 | 
74 |     await cli.start();
75 | }
76 | 
77 | /**
78 |  * 主函数
79 |  */
80 | async function main() {
81 |     // 验证环境变量
82 |     const deepseekApiKey = process.env.DEEPSEEK_API_KEY;
83 |     const deepseekBaseUrl = process.env.DEEPSEEK_BASE_URL;
84 | 
85 |     if (!deepseekApiKey) {
86 |         throw new Error('DEEPSEEK_API_KEY is not set');
87 |     }
88 | 
89 |     if (!deepseekBaseUrl) {
90 |         throw new Error('DEEEPSEEK_BASE_URL is not set');
91 |     }
92 | 
93 |     // 初始化应用
94 |     const { agent, sessionId } = await initializeApp({
95 |         deepseekApiKey,
96 |         deepseekBaseUrl,
97 |     });
98 | 
99 |     // 启动 CLI
100 |     await startCLI(agent, sessionId);
101 | }
102 | 
103 | main().catch(console.error);
104 | ",
