{
  "filePath": "src/agent/index.ts",
  "content": "1 | /**
2 |  * Agent - AI 代理
3 |  * 负责编排 LLM 调用和会话管理
4 |  *
5 |  * 注意：此文件是旧版 Agent，建议使用 index-eventbus.ts 以获得 EventBus 集成
6 |  * 要启用 EventBus 功能，请导入 './index-eventbus' 而不是此文件
7 |  */
8 | import EventEmitter from "events";
9 | import { LLMProvider, LLMResponse, Message, ToolCall, ToolSchema, StreamChunk } from "../providers/base";
10 | import {
11 |   LLMError,
12 |   LLMRetryableError,
13 |   LLMPermanentError,
14 |   LLMAbortedError,
15 |   LLMAuthError,
16 |   LLMNotFoundError,
17 |   isRetryableError,
18 |   isPermanentError,
19 |   isAbortedError,
20 | } from "../providers/errors";
21 | import { ScopedLogger } from "../util/log";
22 | import { SessionManager } from "../session-v2";
23 | import { ToolRegistry, ToolResult } from "../tool/registry";
24 | import { Compaction } from "../session-v2/compaction";
25 | import { AgentContext, getAgentContext } from "../context";
26 | 
27 | 
28 | 
29 | class ToolError extends Error {
30 |     constructor(data: Message) {
31 |         super(data.content || 'Tool execution failed');
32 |         this.name = 'ToolError';
33 |         this.data = data;
34 |     }
35 | 
36 |     /** 工具执行结果数据 */
37 |     data: Message;
38 | }
39 | export interface AgentConfig {
40 |     llmProvider: LLMProvider;
41 |     systemPrompt: string;
42 |     /** 默认工具列表（可选），不传则使用 ToolRegistry 中所有工具 */
43 |     defaultTools?: ToolSchema[];
44 |     /** 最大循环次数，0 或 null 表示无限制，默认 1024 */
45 |     maxLoop?: number | null;
46 |     /** 最大 token 数，默认 8000 */
47 |     maxTokens?: number;
48 |     /** 最大输出 token 数，默认 8000 */
49 |     maxOutputTokens?: number;
50 |     /** 工具并发上限，默认 1 */
51 |     toolConcurrency?: number;
52 |     /** 单次工具调用超时（毫秒），默认 300000 (5分钟) */
53 |     toolTimeoutMs?: number;
54 |     /** 连续错误次数上限，默认 2 */
55 |     noProgressLimit?: number;
56 |     /** 会话 ID */
57 |     sessionId?: string;
58 | }
59 | 
60 | export interface AgentRunOptions {
61 |     silent?: boolean;
62 |     tools?: ToolSchema[];
63 |     /** 启用流式响应 */
64 |     stream?: boolean;
65 |     /** 流式回调函数 */
66 |     streamCallback?: (chunk: StreamChunk) => void;
67 |     /** Abort signal for cancelling the request */
68 |     abortSignal?: AbortSignal;
69 | }
70 | 
71 | export interface AgentResponse {
72 |     content: string;
73 |     role: Message['role'];
74 |     type?: Message['type'];
75 | }
76 | 
77 | export default class Agent extends EventEmitter {
78 |     private llmProvider: LLMProvider;
79 |     private logger: ScopedLogger;
80 |     public readonly sessionManager: SessionManager;
81 |     public readonly context: AgentContext;
82 |     private systemPrompt: string;
83 |     private defaultTools: ToolSchema[] | undefined;
84 |     private maxLoop: number | null | undefined;
85 |     private maxOutputTokens: number;
86 |     private maxTokens: number;
87 |     private noProgressLimit: number;
88 |     private compaction: Compaction;
89 | 
90 |     constructor(config: AgentConfig) {
91 |         super();
92 |         this.llmProvider = config.llmProvider;
93 | 
94 |         // 获取或创建 AgentContext
95 |         this.context = getAgentContext({
96 |             session: {
97 |                 sessionId: config.sessionId || `session_${Date.now()}`,
98 |                 userId: 'default',
99 |             },
100 |         });
101 | 
102 |         // 初始化上下文
103 |         this.context.initialize();
104 | 
105 |         this.sessionManager = new SessionManager({
106 |             sessionId: this.context.sessionId,
107 |             sessionDir: this.context.sessionDir,
108 |             llmProvider: this.llmProvider,
109 |         });
110 | 
111 |         // 将 AgentContext 设置到 ToolRegistry
112 |         ToolRegistry.setAgentContext(this.context);
113 | 
114 |         this.systemPrompt = config.systemPrompt;
115 |         this.defaultTools = config.defaultTools;
116 |         this.logger = new ScopedLogger('Agent');
117 |         this.maxLoop = config.maxLoop;
118 |         const providerMaxOutput = this.llmProvider.maxOutputTokens;
119 |         const providerMaxTokens = this.llmProvider.maxTokens;
120 |         this.maxOutputTokens = Math.min(config.maxOutputTokens ?? providerMaxOutput, providerMaxOutput);
121 |         this.maxTokens = Math.min(config.maxTokens ?? providerMaxTokens, providerMaxTokens);
122 |         this.noProgressLimit = Math.max(0, config.noProgressLimit ?? 2);
123 |         this.sessionManager.maxOutputTokens = this.maxOutputTokens;
124 |         this.sessionManager.maxTokens = this.maxTokens;
125 |         this.compaction = new Compaction({
126 |             maxTokens: this.maxTokens,
127 |             maxOutputTokens: this.maxOutputTokens,
128 |             llmProvider: this.llmProvider,
129 |         });
130 |     }
131 | 
132 |     start() {
133 |         this.sessionManager.init();
134 |     }
135 | 
136 |     /**
137 |      * 执行单个工具调用
138 |      * @returns 工具结果消息，如果执行失败返回包含错误的消息
139 |      */
140 |     private async executeToolCall(toolCall: ToolCall): Promise<Message> {
141 |         const { name, arguments: args } = toolCall.function;
142 |         if (!name) {
143 |             throw new ToolError({
144 |                 role: 'tool',
145 |                 type: 'text',
146 |                 content: 'Error: Tool name is empty',
147 |                 tool_call_id: toolCall.id,
148 |             });
149 |         }
150 | 
151 |         try {
152 |             const result = await ToolRegistry.execute(name, args);
153 |             const content = this.formatToolResult(result);
154 |             this.logger.info(`Tool "${name}" execution successful: ${content}`);
155 |             return {
156 |                 role: 'tool',
157 |                 type: 'text',
158 |                 content,
159 |                 tool_call_id: toolCall.id,
160 |             };
161 |         } catch (error) {
162 |             // 工具执行错误不向上抛出，而是返回错误消息
163 |             const errorMsg = error instanceof Error ? error.message : String(error);
164 |             this.logger.error(`Tool "${name}" execution failed: ${errorMsg}`);
165 | 
166 |             throw new ToolError({
167 |                 role: 'tool',
168 |                 type: 'text',
169 |                 content: `Error: Tool execution failed - ${errorMsg}`,
170 |                 tool_call_id: toolCall.id,
171 |             });
172 |         }
173 |     }
174 | 
175 |     /**
176 |      * 格式化工具结果为字符串内容
177 |      */
178 |     private formatToolResult(result: ToolResult): string {
179 |         if (result.success) {
180 |             // 成功：优先返回 data，其次返回 metadata
181 |             if (result.data !== undefined) {
182 |                 if (typeof result.data === 'string') {
183 |                     return result.data;
184 |                 }
185 |                 return JSON.stringify(result.data, null, 2);
186 |             }
187 |             if (result.metadata) {
188 |                 return JSON.stringify(result.metadata, null, 2);
189 |             }
190 |             return 'Tool executed successfully';
191 |         } else {
192 |             // 失败：返回错误信息
193 |             return `Error: ${result.error || 'Unknown error'}`;
194 |         }
195 |     }
196 | 
197 |     /**
198 |      * 处理工具调用，返回是否有工具被调用
199 |      * @returns { hasToolCalls: boolean, hasError: boolean }
200 |      */
201 |     private async handleToolCalls(
202 |         llmResponse: LLMResponse,
203 |         spinner: ReturnType<ScopedLogger['spinner']>
204 |     ): Promise<{ hasToolCalls: boolean; hasError: boolean }> {
205 |         if (!llmResponse.tool_calls || llmResponse.tool_calls.length === 0) {
206 |             return { hasToolCalls: false, hasError: false };
207 |         }
208 | 
209 |         const toolResults: Message[] = [];
210 |         let hasExecutionError = false;
211 | 
212 | 
213 |         // 顺序执行工具调用（避免并发导致的资源竞争问题）
214 |         for (const call of llmResponse.tool_calls) {
215 |             try {
216 |                 const result = await this.executeToolCall(call);
217 |                 toolResults.push(result);
218 |                 // 检查是否是错误结果
219 |             } catch (error:any) {
220 |                 if (error instanceof ToolError) {
221 |                     toolResults.push(error.data);
222 |                     hasExecutionError = true;
223 |                 } else {
224 |                     // 其他未知错误继续抛出
225 |                     toolResults.push({
226 |                         role: 'tool',
227 |                         type: 'text',
228 |                         content: `Error: Unknown tool execution error - ${error?.message}`,
229 |                         tool_call_id: call.id,
230 |                     });
231 |                 }
232 |             }
233 |         }
234 | 
235 |         this.sessionManager.addMessage(toolResults);
236 | 
237 |         // 提取 content 字段进行拼接
238 |         const summaries = toolResults
239 |             .map(r => {
240 |                 const content = r.content ?? '';
241 |                 return content.length > 50 ? content.slice(0, 47) + '...' : content;
242 |             })
243 |             .join(', ');
244 | 
245 |         if (hasExecutionError) {
246 |             spinner.warn(`Tool calls completed with errors: ${summaries}`);
247 |         } else {
248 |             spinner.succeed(`Tool calls: ${summaries}`);
249 |         }
250 | 
251 |         return { hasToolCalls: true, hasError: hasExecutionError };
252 |     }
253 | 
254 |     /**
255 |     /**
256 |      * 运行 Agent 处理用户查询
257 |      * @param query 用户查询
258 |      * @param options 选项
259 |      * @returns Agent 响应
260 |      */
261 |     async run(
262 |         query: string,
263 |         options?: AgentRunOptions
264 |     ): Promise<AgentResponse | null> {
265 |         const tools = options?.tools ?? this.defaultTools ?? [];
266 |         let consecutiveErrorCount = 0;
267 |         let networkErrorCount = 0;
268 |         let i = 0;
269 |         const streamEnabled = options?.stream ?? false;
270 |         const streamCallback = options?.streamCallback;
271 |         const externalAbortSignal = options?.abortSignal;
272 | 
273 |         // 添加用户消息
274 |         this.sessionManager.addMessage({
275 |             role: 'user',
276 |             type: 'text',
277 |             content: query,
278 |         });
279 | 
280 |         while (true) {
281 |             i++;
282 | 
283 |             // maxLoop 为 0 或 null 表示无限制
284 |             if (this.maxLoop && this.maxLoop > 0 && i > this.maxLoop) {
285 |                 return {
286 |                     content: `Max loop limit reached (${this.maxLoop})`,
287 |                     role: 'assistant',
288 |                 };
289 |             }
290 | 
291 |             const meessages = this.sessionManager.getMessages();
292 |             const { totalUsed, usableLimit } = this.compaction.getToken(meessages);
293 | 
294 |             this.logger.info(`totalUsed: ${totalUsed}/${usableLimit}`);
295 | 
296 |             const { isCompacted, list: llmMessages } = await this.compaction.compact(meessages);
297 | 
298 |             if (isCompacted) {
299 |                 this.sessionManager.setMessages(llmMessages);
300 |             }
301 | 
302 |             const spinner = this.logger.spinner(`Thinking-${i}...`);
303 | 
304 |             // 创建 AbortController 用于取消请求
305 |             const abortController = new AbortController();
306 |             const currentAbortSignal = externalAbortSignal || abortController.signal;
307 | 
308 |             // 如果有外部 abortSignal，监听它以同步内部的 abortController
309 |             if (externalAbortSignal) {
310 |                 externalAbortSignal.addEventListener('abort', () => {
311 |                     abortController.abort();
312 |                 });
313 |             }
314 | 
315 |             try {
316 |                 // 构建包装的流式回调，用于停止 spinner
317 |                 let spinnerStopped = false;
318 |                 const wrappedStreamCallback = streamCallback ? (chunk: StreamChunk) => {
319 |                     if (!spinnerStopped) {
320 |                         spinner.stop();
321 |                         spinnerStopped = true;
322 |                     }
323 |                     // 调用原始回调
324 |                     streamCallback(chunk);
325 |                     // 发送事件
326 |                     this.emit('stream-chunk', chunk);
327 |                 } : undefined;
328 | 
329 |                 const llmResponse = await this.llmProvider.generate(
330 |                     [
331 |                         { role: 'system', content: this.systemPrompt },
332 |                         ...llmMessages,
333 |                     ],
334 |                     {
335 |                         model: process.env.AI_MODEL,
336 |                         tools: tools.length > 0 ? tools : undefined,
337 |                         max_tokens: this.maxOutputTokens,
338 |                         stream: streamEnabled,
339 |                         streamCallback: wrappedStreamCallback,
340 |                         abortSignal: currentAbortSignal,
341 |                     }
342 |                 );
343 | 
344 |                 if (!llmResponse) {
345 |                     throw new Error('LLM response is null');
346 |                 }
347 | 
348 |                 this.sessionManager.addMessage(llmResponse);
349 | 
350 |                 const { hasToolCalls, hasError: toolHasError } = await this.handleToolCalls(llmResponse, spinner);
351 | 
352 |                 if (toolHasError) {
353 |                     // 工具调用出现错误，LLM 需要根据错误信息决定下一步
354 |                     this.logger.warn('Tool execution had errors, continuing for LLM to handle');
355 |                     // 不增加 consecutiveErrorCount，因为工具错误是预期的处理流程
356 |                     continue;
357 |                 }
358 | 
359 |                 if (!hasToolCalls) {
360 |                     // 单次无工具调用即返回，无需继续循环
361 |                     // 正常结束状态：'stop'、'eos'、undefined；其他值可能是异常
362 |                     const messages = this.sessionManager.getMessages();
363 |                     const lastMessageRole = messages[messages.length - 1].role;
364 |                     const lastMessageType = messages[messages.length - 1].type;
365 | 
366 |                     const validEnd = ['stop', 'eos', undefined].includes(llmResponse.finishReason as string);
367 |                     if (!validEnd) {
368 |                         spinner.fail(`Unexpected finishReason: ${llmResponse.finishReason}`);
369 |                         consecutiveErrorCount++;
370 | 
371 |                         if (consecutiveErrorCount > this.noProgressLimit) {
372 |                             return {
373 |                                 content: `Max error limit reached: unexpected finishReason "${llmResponse.finishReason}"`,
374 |                                 role: 'assistant',
375 |                             };
376 |                         }
377 |                         // 继续循环，尝试让 LLM 恢复
378 |                         continue;
379 |                     } else if (lastMessageRole === 'assistant' && lastMessageType === 'text') {
380 | 
381 |                         spinner.succeed('\nTask success!');
382 |                         spinner.clear();
383 |                         return {
384 |                             content: llmResponse?.content ?? '',
385 |                             role: 'assistant',
386 |                         };
387 |                     } else if (lastMessageRole === 'assistant' && lastMessageType === 'summary') {
388 |                         continue;
389 |                     }
390 |                 }
391 | 
392 |                 // 工具调用成功，重置连续错误计数
393 |                 consecutiveErrorCount = 0;
394 |                 networkErrorCount = 0;
395 | 
396 |             } catch (error) {
397 |                 // 使用新的错误类型处理
398 |                 const errorMsg = error instanceof Error ? error.message : String(error);
399 | 
400 |                 // 处理取消错误
401 |                 if (isAbortedError(error)) {
402 |                     spinner.fail('Task cancelled');
403 |                     this.logger.info('Task cancelled by user');
404 |                     this.sessionManager.addMessage({
405 |                         role: 'assistant',
406 |                         type: 'text',
407 |                         content: '\n[Task cancelled - press Enter to continue]',
408 |                         tool_calls: undefined,
409 |                     });
410 |                     return {
411 |                         content: '[Task cancelled]',
412 |                         role: 'assistant',
413 |                     };
414 |                 }
415 | 
416 |                 // 处理可重试错误（网络错误、服务器错误、速率限制）
417 |                 if (isRetryableError(error)) {
418 |                     networkErrorCount++;
419 | 
420 |                     // 获取建议的重试延迟
421 |                     const backoffMs = error.getBackoff(networkErrorCount);
422 |                     spinner.warn(`Retryable error (attempt ${networkErrorCount}): ${errorMsg}`);
423 | 
424 |                     const maxNetworkRetries = 3;
425 |                     if (networkErrorCount > maxNetworkRetries) {
426 |                         this.logger.error(`Max retries (${maxNetworkRetries}) reached`);
427 |                         this.sessionManager.addMessage({
428 |                             role: 'assistant',
429 |                             type: 'text',
430 |                             content: `[Retryable Error] After ${maxNetworkRetries} attempts: ${errorMsg}`,
431 |                         });
432 |                         return {
433 |                             content: `Service unavailable after ${maxNetworkRetries} retries. ${errorMsg}`,
434 |                             role: 'assistant',
435 |                         };
436 |                     }
437 | 
438 |                     this.logger.info(`Retrying in ${backoffMs / 1000}s...`);
439 |                     await new Promise(resolve => setTimeout(resolve, backoffMs));
440 |                     continue;
441 |                 }
442 | 
443 |                 // 处理永久性错误（认证失败、模型不存在、参数错误等）
444 |                 if (isPermanentError(error)) {
445 |                     spinner.fail('Permanent error occurred');
446 |                     this.logger.error(`Permanent error: ${errorMsg}`);
447 | 
448 |                     let userMessage = `API Error: ${errorMsg}`;
449 | 
450 |                     // 特殊处理认证错误
451 |                     if (error instanceof LLMAuthError) {
452 |                         userMessage = 'Authentication failed. Please check your API key configuration.';
453 |                     }
454 |                     // 特殊处理模型不存在错误
455 |                     else if (error instanceof LLMNotFoundError) {
456 |                         if (error.resourceType === 'model') {
457 |                             userMessage = `Model not found. Please check AI_MODEL configuration. ${errorMsg}`;
458 |                         } else {
459 |                             userMessage = `Resource not found. ${errorMsg}`;
460 |                         }
461 |                     }
462 | 
463 |                     this.sessionManager.addMessage({
464 |                         role: 'assistant',
465 |                         type: 'text',
466 |                         content: `[Permanent Error] ${userMessage}`,
467 |                     });
468 | 
469 |                     return {
470 |                         content: userMessage,
471 |                         role: 'assistant',
472 |                     };
473 |                 }
474 | 
475 |                 // 处理其他未知错误
476 |                 spinner.fail(`Error: ${errorMsg}`);
477 |                 this.logger.error(`Unexpected error: ${errorMsg}`);
478 | 
479 |                 this.sessionManager.addMessage({
480 |                     role: 'assistant',
481 |                     type: 'text',
482 |                     content: `[Error] ${errorMsg}`,
483 |                 });
484 | 
485 |                 consecutiveErrorCount++;
486 | 
487 |                 if (consecutiveErrorCount > this.noProgressLimit) {
488 |                     return {
489 |                         content: `Max error limit reached (${this.noProgressLimit} consecutive errors). Last error: ${errorMsg}`,
490 |                         role: 'assistant',
491 |                     };
492 |                 }
493 |             }
494 |         }
495 |     }
496 | }
497 | ",
  "range": {
    "startLine": 1,
    "endLine": 497
  }
}

{
