{
  "filePath": "src/session-v2/compaction.ts",
  "content": "1 | import { Message, LLMProvider } from "../providers/base";
2 | import { OpenAIProvider } from "../providers/openai";
3 | import { ScopedLogger } from "../util/log";
4 | 
5 | export class Compaction {
6 |   private readonly maxTokens: number;
7 |   private readonly maxOutputTokens: number;
8 |   private readonly triggerRatio = 0.92; // 92% 触发压缩
9 |   private keepMessagesNum: number = 40;
10 |   logger: ScopedLogger;
11 |   llmProvider: LLMProvider;
12 | 
13 |   constructor(config: { maxTokens: number; maxOutputTokens: number; llmProvider: LLMProvider; keepMessagesNum?: number }) {
14 |     this.maxTokens = config.maxTokens;
15 |     this.maxOutputTokens = config.maxOutputTokens;
16 |     this.logger = new ScopedLogger("Compaction");
17 |     this.llmProvider = config.llmProvider;
18 |     this.keepMessagesNum = config.keepMessagesNum || this.keepMessagesNum;
19 |   }
20 | 
21 |   getToken(history: Message[]) {
22 |     const totalUsed = this.calculateTotalUsage(history);
23 |     const usableLimit = this.maxTokens - this.maxOutputTokens;
24 | 
25 |     return {
26 |       totalUsed,
27 |       usableLimit: usableLimit * this.triggerRatio
28 |     };
29 |   }
30 | 
31 |   /**
32 |    * 性能优化：构建 tool_call_id 到 assistant 索引的映射表
33 |    * 时间复杂度：O(n)，其中 n 是 history 的长度
34 |    * @returns Map<tool_call_id, assistant_index>
35 |    */
36 |   private buildToolCallToAssistantIndex(messages: Message[]): Map<string, number> {
37 |     const index = new Map<string, number>();
38 | 
39 |     // 遍历所有消息，记录每个 tool_call_id 对应的 assistant 索引
40 |     for (let i = 0; i < messages.length; i++) {
41 |       const msg = messages[i];
42 |       if (msg.role === 'assistant' && msg.tool_calls) {
43 |         for (const call of msg.tool_calls) {
44 |           if (call.id) {
45 |             index.set(call.id, i);
46 |           }
47 |         }
48 |       }
49 |     }
50 | 
51 |     return index;
52 |   }
53 | 
54 |   /**
55 |    * 性能优化：构建消息列表中 tool 消息的索引映射
56 |    * 时间复杂度：O(m)，其中 m 是 messages 的长度
57 |    * @returns Map<tool_call_id, message>
58 |    */
59 |   private buildToolMessageMap(messages: Message[]): Map<string, Message> {
60 |     const map = new Map<string, Message>();
61 | 
62 |     for (const msg of messages) {
63 |       if (msg.role === 'tool' && msg.tool_call_id) {
64 |         map.set(msg.tool_call_id, msg);
65 |       }
66 |     }
67 | 
68 |     return map;
69 |   }
70 | 
71 |   async compact(history: Message[]): Promise<{
72 |     isCompacted: boolean,
73 |     summaryMessage: Message | null,
74 |     list: Message[]
75 |   }> {
76 |     const totalUsed = this.calculateTotalUsage(history);
77 |     const usableLimit = this.maxTokens - this.maxOutputTokens;
78 |     const threshold = usableLimit * this.triggerRatio;
79 | 
80 |     // 只有当消息数量超过保留数量且 token 达到阈值时，才触发压缩
81 |     const shouldCompact = history.length > this.keepMessagesNum && totalUsed >= threshold;
82 | 
83 |     // 如果没达到压缩条件，直接返回原数据
84 |     if (!shouldCompact) {
85 |       return {
86 |         isCompacted: false,
87 |         summaryMessage: null,
88 |         list: history
89 |       };
90 |     }
91 | 
92 |     this.logger.info(
93 |       `[Compaction] 触发压缩。当前 Token: ${totalUsed}, 阈值: ${Math.floor(threshold)}`
94 |     );
95 | 
96 |     let activeMessages = history.slice(-this.keepMessagesNum); // 保护区
97 |     let pendingMessages = history.slice(0, -this.keepMessagesNum); // 待压缩区
98 | 
99 |     // 限制保护区的最大膨胀倍数（防止从 6 条膨胀到 100+ 条）
100 |     const MAX_ACTIVE_SIZE = this.keepMessagesNum * 2;
101 | 
102 |     // 检查保护区的所有 tool 消息，确保它们的配对 assistant 以及所有相关的 tool 回复都被保留
103 |     // 需要处理多个 assistant 的情况（连续多次工具调用）
104 | 
105 |     // 性能优化：一次性构建所有索引，避免 O(n²) 的多次查找
106 |     // 时间复杂度：O(n + m + k)，其中 n=history长度，m=pending长度，k=active长度
107 |     const toolCallToAssistantIndex = this.buildToolCallToAssistantIndex(history);
108 |     const pendingToolMap = this.buildToolMessageMap(pendingMessages);
109 |     const activeToolMap = this.buildToolMessageMap(activeMessages);
110 | 
111 |     const toolMessagesInActive = activeMessages.filter(m =>
112 |       m.role === 'tool' && m.tool_call_id  // 过滤掉无效的 tool_call_id
113 |     );
114 | 
115 |     if (toolMessagesInActive.length > 0) {
116 |       // 收集所有需要保留的 assistant 消息和需要重新排序的 tool 回复
117 |       // 修复：将 tool 回复与对应的 assistant 分组，确保消息顺序正确
118 |       const assistantsToKeep: Map<string, { message: Message; index: number; tools: Message[] }> = new Map();
119 |       // 跟踪从 pendingMessages 移到 toolsToKeep 的 tool_call_id
120 |       const movedToolCallIds = new Set<string>();
121 | 
122 |       // 计算分割点，用于判断 assistant 在哪个区域
123 |       // history[:splitPoint] = pendingMessages
124 |       // history[splitPoint:] = activeMessages
125 |       const splitPoint = history.length - this.keepMessagesNum;
126 | 
127 |       // 修复：识别唯一需要处理的 assistant 索引
128 |       // 这确保我们只处理每个 assistant 一次，但会收集该 assistant 的所有 tools
129 |       const uniqueAssistantIndices = new Set<number>();
130 |       for (const toolMessage of toolMessagesInActive) {
131 |         const toolCallId = toolMessage.tool_call_id;
132 |         if (!toolCallId) continue;
133 |         const assistantIndex = toolCallToAssistantIndex.get(toolCallId);
134 |         if (assistantIndex !== undefined) {
135 |           uniqueAssistantIndices.add(assistantIndex);
136 |         }
137 |       }
138 | 
139 |       // 为每个唯一的 assistant 处理一次，收集其所有 tools
140 |       for (const assistantIndex of uniqueAssistantIndices) {
141 |         // 从 history 中获取 assistant 消息
142 |         const assistantMessage = history[assistantIndex];
143 |         if (!assistantMessage || !assistantMessage.tool_calls || assistantMessage.tool_calls.length === 0) {
144 |           continue;
145 |         }
146 | 
147 |         const assistantKey = assistantIndex.toString();
148 |         const toolCalls = assistantMessage.tool_calls?.filter(call => call.id) || [];
149 | 
150 |         // 收集该 assistant 的所有 tools（从两个区域按 tool_calls 顺序收集）
151 |         const allTools: Message[] = [];
152 |         for (const toolCall of toolCalls) {
153 |           // 先检查 active 区域，再检查 pending 区域
154 |           let toolMessage = activeToolMap.get(toolCall.id);
155 |           if (!toolMessage) {
156 |             toolMessage = pendingToolMap.get(toolCall.id);
157 |             if (toolMessage) {
158 |               movedToolCallIds.add(toolCall.id); // 跟踪从 pending 移动的 tool
159 |             }
160 |           }
161 |           if (toolMessage) {
162 |             allTools.push(toolMessage);
163 |           }
164 |         }
165 | 
166 |         const toolCallIds = toolCalls.map(c => c.id);
167 | 
168 |         // 无论 assistant 在哪个区域，都从 activeMessages 中移除它的 tools（稍后会重新添加）
169 |         // 这避免 tools 在 activeMessages 中被重复计算
170 |         activeMessages = activeMessages.filter(m => {
171 |           // 如果 assistant 在 active 区域，也要移除它
172 |           if (assistantIndex >= splitPoint && m === assistantMessage) return false;
173 |           // 移除这些 tool 回复（无论 assistant 在哪，都要移除 active 中的 tools）
174 |           if (m.role === 'tool' && toolCallIds.includes(m.tool_call_id || '')) return false;
175 |           return true;
176 |         });
177 | 
178 |         // 记录这个 assistant 需要保留，以及它的所有 tools
179 |         assistantsToKeep.set(assistantKey, {
180 |           message: assistantMessage,
181 |           index: assistantIndex,
182 |           tools: allTools,
183 |         });
184 | 
185 |         this.logger.info(
186 |           `[Compaction] 处理 assistant（索引 ${assistantIndex}）：` +
187 |           `${toolCalls.length} 个 tool_calls，收集到 ${allTools.length} 个 tool 回复`
188 |         );
189 |       }
190 | 
191 |       // 将需要保留的 assistant 和 tool 回复按正确顺序加入保护区
192 |       if (assistantsToKeep.size > 0) {
193 |         // 按索引排序 assistants（保持原始顺序）
194 |         const sortedAssistantsWithTools = Array.from(assistantsToKeep.values())
195 |           .sort((a, b) => a.index - b.index);
196 | 
197 |         // 从 pendingMessages 中移除这些 assistants（如果它们在 pendingMessages 中）
198 |         // 同时移除已移动的 tool 消息
199 |         // 修复：使用 splitPoint 而不是 pendingMessages.length
200 |         // item.index 是原 history 数组的索引，需要与 splitPoint 比较
201 |         const indicesToRemove = Array.from(assistantsToKeep.values())
202 |           .filter(item => item.index < splitPoint)
203 |           .map(item => item.index);
204 | 
205 |         if (indicesToRemove.length > 0 || movedToolCallIds.size > 0) {
206 |           pendingMessages = pendingMessages.filter((msg, i) => {
207 |             // 移除 assistant 消息
208 |             if (indicesToRemove.includes(i)) return false;
209 |             // 移除已移动的 tool 消息
210 |             if (msg.role === 'tool' && msg.tool_call_id && movedToolCallIds.has(msg.tool_call_id)) return false;
211 |             return true;
212 |           });
213 |         }
214 | 
215 |         // 构建新的 activeMessages，将每个 assistant 与它的 tools 交错排列
216 |         // 正确的结构应该是：Assistant1, Tool1, Tool2, Assistant2, Tool3, Tool4, ...
217 |         const newActiveMessages: Message[] = [];
218 | 
219 |         for (const { message: assistantMsg, tools: assistantTools } of sortedAssistantsWithTools) {
220 |           newActiveMessages.push(assistantMsg);
221 |           newActiveMessages.push(...assistantTools);
222 |         }
223 | 
224 |         // 添加剩余的 activeMessages
225 |         newActiveMessages.push(...activeMessages);
226 | 
227 |         // 检查是否超过最大限制
228 |         if (newActiveMessages.length > MAX_ACTIVE_SIZE) {
229 |           this.logger.warn(
230 |             `[Compaction] 保护区膨胀：从 ${this.keepMessagesNum} 条增长到 ${newActiveMessages.length} 条` +
231 |             `(超过最大限制 ${MAX_ACTIVE_SIZE})，将进行裁剪`
232 |           );
233 | 
234 |           // 计算 assistants 和 tools 的总消息数
235 |           const totalAssistantsAndTools = sortedAssistantsWithTools.reduce(
236 |             (sum, item) => sum + 1 + item.tools.length, 0);
237 | 
238 |           // 裁剪：保留前面的 assistants 和 tools，裁剪后面的原始 activeMessages
239 |           const overflow = newActiveMessages.length - MAX_ACTIVE_SIZE;
240 |           if (overflow > 0 && totalAssistantsAndTools < MAX_ACTIVE_SIZE) {
241 |             // 可以安全地裁剪后面的消息
242 |             newActiveMessages.length = MAX_ACTIVE_SIZE;
243 |           }
244 |         }
245 | 
246 |         activeMessages = newActiveMessages;
247 | 
248 |         // 计算统计信息
249 |         const totalAssistants = sortedAssistantsWithTools.length;
250 |         const totalTools = sortedAssistantsWithTools.reduce((sum, item) => sum + item.tools.length, 0);
251 | 
252 |         this.logger.info(
253 |           `[Compaction] 已将 ${totalAssistants} 个 assistant 和 ${totalTools} 个 tool 回复移到保护区` +
254 |           `（保护区大小：${activeMessages.length}）`
255 |         );
256 |       }
257 |     }
258 | 
259 |     // 3. 提取之前的摘要（如果存在）
260 |     let previousSummary = "";
261 |     if (pendingMessages.length > 0 && pendingMessages[0].type === "summary") {
262 |       previousSummary = pendingMessages[0].content;
263 |       pendingMessages = pendingMessages.slice(1);
264 |     }
265 | 
266 |     // 4. 将待压缩的消息序列化为文本
267 |     // 特别处理：将 tool 消息与其 result 格式化，方便 LLM 理解
268 |     const textToSummarize = pendingMessages
269 |       .map((m) => {
270 |         const prefix = m.type ? `[${m.role}:${m.type}]` : `[${m.role}]`;
271 |         // 如果内容过长（如巨大的代码输出），在摘要前进行初步截断
272 |         const content =
273 |           m.content.length > 2000
274 |             ? m.content.slice(0, 1000) + "...(省略)..."
275 |             : m.content;
276 |         return `${prefix}: ${content}`;
277 |       })
278 |       .join("\n");
279 | 
280 |     // 5. 执行异步摘要
281 |     const newSummaryContent = await this.summarizer(
282 |       textToSummarize,
283 |       previousSummary,
284 |     );
285 | 
286 |     const summaryMessage: Message = {
287 |       role: "assistant",
288 |       type: "summary",
289 |       content: `${newSummaryContent}`,
290 |     };
291 | 
292 |     // 6. 重组历史
293 |     const newHistory = [summaryMessage, ...activeMessages, {
294 |       role: "user" as const,
295 |       type: "text" as const,
296 |       content: "Confirm task completion. If the task is not finished, define the next actions and continue execution until all user requirements are satisfied.",
297 |     }];
298 | 
299 |     return {
300 |       isCompacted: true,
301 |       summaryMessage,
302 |       list: newHistory
303 |     };
304 | 
305 |   }
306 | 
307 |   /**
308 |    * 计算整个对话数组的 Token 用量
309 |    */
310 |   public calculateTotalUsage(messages: Message[]): number {
311 |     return messages.reduce((acc, m) => {
312 |       // 每条消息基础开销 4 tokens (role, name, newline)
313 |       return acc + this.estimate(JSON.stringify(m)) + 4;
314 |     }, 0);
315 |   }
316 | 
317 |   /**
318 |    * 估算单段文本的 Token
319 |    */
320 |   private estimate(text: string): number {
321 |     if (!text) return 0;
322 |     return Math.ceil(
323 |       text.length / 4,
324 |     );
325 |   }
326 | 
327 |   async summarizer(textToSummarize: string, previousSummary?: string) {
328 | 
329 | 
330 |     const spinner = this.logger.spinner("上下文压缩...");
331 | 
332 |     const llmResponse = await this.llmProvider.generate(
333 |       [
334 |         {
335 |           role: "user",
336 |           content: `You are an expert conversation compressor. Compress the conversation history into a structured summary organized in the following 8 sections:
337 | 1. **Primary Request and Intent**: What is the user's core goal?
338 | 2. **Key Technical Concepts**: Frameworks, libraries, tech stacks, etc., involved in the conversation.
339 | 3. **Files and Code Sections**: All file paths mentioned or modified.
340 | 4. **Errors and Fixes**: Record error messages encountered and their solutions.
341 | 5. **Problem Solving**: The thought process and decision path for solving the problem.
342 | 6. **All User Messages**: Preserve key instructions and feedback from the user.
343 | 7. **Pending Tasks**: Work items that remain unfinished.
344 | 8. **Current Work**: The progress at the point the conversation was interrupted.
345 | 
346 | ${previousSummary ? `<previous_summary>
347 |   ${previousSummary}
348 | </previous_summary>
349 | ` : ''}
350 | 
351 | <current_mesage_history>
352 | ${textToSummarize}
353 | </current_mesage_history>
354 | 
355 |   ## Requirements:
356 | - Maintain high density and accuracy of information
357 | - Highlight key technical decisions and solutions
358 | - Ensure continuity of context
359 | - Retain all important file paths
360 | - Use concise English expression
361 | `,
362 |         },
363 |       ],
364 |       {
365 |         model: process.env.AI_MODEL,
366 |         max_tokens: 8000,
367 |         temperature: 0.3,
368 |       },
369 |     );
370 |     spinner.succeed("上下文压缩成功");
371 |     return llmResponse?.content || '';
372 | 
373 |   }
