  "content": "1 | /**
2 |  * CLI - 交互式命令行界面
3 |  * 使用 prompts 库实现稳定的交互
4 |  */
5 | import { execSync } from 'node:child_process';
6 | import readline from 'readline';
7 | import { ScopedLogger } from '../util/log';
8 | import { Ora } from 'ora';
9 | import Agent from '../agent';
10 | import { executeCommand } from './commands';
11 | import { InputHistory } from './utils';
12 | import { readWithHistory } from './utils/reader';
13 | import type { CommandContext } from './commands/types';
14 | 
15 | export interface CLIConfig {
16 |     agent: Agent;
17 |     sessionId?: string;
18 |     prompt?: string;
19 | }
20 | 
21 | export class CLI {
22 |     private agent: Agent;
23 |     private sessionId: { value: string };
24 |     private promptText: string;
25 |     private running: boolean;
26 |     private logger: ScopedLogger;
27 |     private inputHistory: InputHistory;
28 |     private reconnectAttempts: number = 0;
29 |     private readonly maxReconnectAttempts = 3;
30 |     private stdinClosed: boolean = false;
31 |     private abortController: AbortController | null = null;
32 |     private isProcessingTask: boolean = false;
33 |     private escKeyHandler: ((key: string) => void) | null = null;
34 | 
35 |     constructor(config: CLIConfig) {
36 |         this.agent = config.agent;
37 |         // 使用 AgentContext 中的 sessionId
38 |         this.sessionId = { value: config.sessionId || this.agent.context.sessionId };
39 |         this.promptText = config.prompt || 'You';
40 |         this.running = false;
41 |         this.logger = new ScopedLogger('CLI');
42 |         this.inputHistory = new InputHistory();
43 | 
44 |         // 设置全局未捕获异常处理
45 |         this.setupGlobalErrorHandlers();
46 |     }
47 | 
48 |     /**
49 |      * 设置全局错误处理，防止进程意外退出
50 |      */
51 |     private setupGlobalErrorHandlers(): void {
52 |         // 处理未捕获的 Promise rejection
53 |         process.on('unhandledRejection', (reason, promise) => {
54 |             this.logger.error(`Unhandled Rejection at: ${promise}, reason: ${reason}`);
55 |             this.logger.warn('Attempting to recover...');
56 |         });
57 | 
58 |         // 处理未捕获的异常
59 |         process.on('uncaughtException', (error) => {
60 |             this.logger.error(`Uncaught Exception: ${error.message}`);
61 |             this.logger.error(error.stack || '');
62 |             this.logger.warn('CLI encountered a fatal error, attempting to recover...');
63 | 
64 |             // 尝试恢复，如果多次失败则退出
65 |             this.reconnectAttempts++;
66 |             if (this.reconnectAttempts <= this.maxReconnectAttempts) {
67 |                 this.logger.info(`Reconnection attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts}`);
68 |                 setTimeout(() => {
69 |                     this.running = true;
70 |                     this.mainLoop().catch(console.error);
71 |                 }, 1000);
72 |             } else {
73 |                 this.logger.error('Max reconnection attempts reached. Exiting...');
74 |                 this.shutdown(1);
75 |             }
76 |         });
77 | 
78 |         // 处理 SIGHUP/SIGTERM
79 |         const cleanup = () => {
80 |             this.logger.info('Received termination signal, shutting down gracefully...');
81 |             this.shutdown(0);
82 |         };
83 |         process.on('SIGHUP', cleanup);
84 |         process.on('SIGTERM', cleanup);
85 | 
86 |         // 处理 stdin 关闭
87 |         process.stdin.on('close', () => {
88 |             if (!this.stdinClosed) {
89 |                 this.stdinClosed = true;
90 |                 this.logger.info('Stdin closed');
91 |                 this.shutdown(0);
92 |             }
93 |         });
94 |     }
95 | 
96 |     /**
97 |      * 启动 ESC 键监听器
98 |      */
99 |     private startEscListener(): void {
100 |         if (this.escKeyHandler) {
101 |             return;
102 |         }
103 | 
104 |         readline.emitKeypressEvents(process.stdin);
105 |         if (process.stdin.isRaw !== true) {
106 |             process.stdin.setRawMode(true);
107 |         }
108 | 
109 |         this.escKeyHandler = (key: string) => {
110 |             // ESC 键的转义序列是 \x1B 或 \u001b
111 |             if (key === '\x1B' || key === '\u001b') {
112 |                 this.cancelCurrentTask();
113 |             }
114 |             // 同时支持 Ctrl+C 作为取消
115 |             else if (key === '\x03') {
116 |                 this.cancelCurrentTask();
117 |             }
118 |         };
119 | 
120 |         process.stdin.on('keypress', this.escKeyHandler);
121 |     }
122 | 
123 |     /**
124 |      * 停止 ESC 键监听器
125 |      */
126 |     private stopEscListener(): void {
127 |         if (this.escKeyHandler) {
128 |             process.stdin.off('keypress', this.escKeyHandler);
129 |             this.escKeyHandler = null;
130 |         }
131 |     }
132 | 
133 |     /**
134 |      * 取消当前正在执行的任务
135 |      */
136 |     private cancelCurrentTask(): void {
137 |         if (this.isProcessingTask && this.abortController) {
138 |             this.logger.info('Cancelling current task...');
139 |             this.abortController.abort();
140 |             this.isProcessingTask = false;
141 |             this.stopEscListener();
142 |             console.log('\n\n⏹️  Task cancelled. Press Enter to continue.\n');
143 |         }
144 |     }
145 | 
146 |     /**
147 |      * 启动 CLI
148 |      */
149 |     async start(): Promise<void> {
150 |         this.running = true;
151 | 
152 |         if (process.platform === 'win32') {
153 |             try {
154 |                 execSync('chcp 65001>nul');
155 |             } catch (_error) {
156 |                 // 忽略失败并保持默认代码页。
157 |             }
158 |         }
159 |         this.printWelcome();
160 | 
161 |         await this.mainLoop();
162 |     }
163 | 
164 |     /**
165 |      * 主循环 - 处理用户输入
166 |      */
167 |     private async mainLoop(): Promise<void> {
168 |         while (this.running) {
169 |             try {
170 |                 const input = await this.getInput();
171 | 
172 |                 const trimmed = input.trim();
173 |                 if (!trimmed) continue;
174 | 
175 |                 await this.handleInput(trimmed);
176 | 
177 |                 // 成功处理后重置重连计数
178 |                 this.reconnectAttempts = 0;
179 | 
180 |             } catch (error) {
181 |                 if (error instanceof Error) {
182 |                     // 检查是否是用户取消（Ctrl+C）
183 |                     if ((error as any).cancelled || error.message === 'user cancelled') {
184 |                         this.logger.info('Received interrupt signal, exiting...');
185 |                         this.shutdown(0);
186 |                         return;
187 |                     }
188 | 
189 |                     this.logger.error(`Error in main loop: ${error.message}`);
190 |                 } else {
191 |                     this.logger.error(`Unknown error: ${error}`);
192 |                 }
193 |             }
194 |         }
195 |     }
196 | 
197 |     /**
198 |      * 获取用户输入（支持历史记录）
199 |      */
200 |     private async getInput(): Promise<string> {
201 |         try {
202 |             const result = await readWithHistory(this.promptText, this.inputHistory);
203 |             // 更新历史记录引用
204 |             this.inputHistory = result.history;
205 |             return result.value;
206 |         } catch (error) {
207 |             // 如果是用户取消，直接抛出
208 |             if (error instanceof Error && (error as any).cancelled) {
209 |                 throw error;
210 |             }
211 |             throw error;
212 |         }
213 |     }
214 | 
215 |     /**
216 |      * 处理用户输入
217 |      */
218 |     private async handleInput(input: string): Promise<void> {
219 |         const context: CommandContext = {
220 |             agent: this.agent,
221 |             sessionManager: this.agent.sessionManager,
222 |             running: { value: this.running },
223 |             sessionId: this.sessionId,
224 |         };
225 | 
226 |         const isCommand = await executeCommand(input, context);
227 | 
228 |         // 更新运行状态
229 |         this.running = context.running.value;
230 | 
231 |         // 同步 sessionId 从 AgentContext
232 |         this.sessionId.value = this.agent.context.sessionId;
233 | 
234 |         if (!isCommand) {
235 |             await this.handleChat(input);
236 |         }
237 |     }
238 | 
239 |     /**
240 |      * 处理对话输入（带流式输出）
241 |      */
242 |     private async handleChat(input: string): Promise<void> {
243 |         // 创建新的 AbortController 用于此任务
244 |         this.abortController = new AbortController();
245 |         this.isProcessingTask = true;
246 | 
247 |         // 启动 ESC 监听
248 |         this.startEscListener();
249 | 
250 |         let spinner: Ora | null = this.logger.spinner('Thinking...');
251 | 
252 |         try {
253 |             // 输出标题
254 |             console.log('\n🤖 Agent:');
255 | 
256 |             // 禁用自动换行，确保长文本可正确复制
257 |             // \x1B[?7l 禁用自动换行，\x1B[?7h 启用自动换行
258 |             process.stdout.write('\x1B[?7l');
259 | 
260 |             // 流式响应
261 |             const response = await this.agent.run(input, {
262 |                 silent: true,
263 |                 stream: true,
264 |                 streamCallback: (chunk) => {
265 |                     // 先停止 spinner
266 |                     if (spinner) {
267 |                         spinner.stop();
268 |                         spinner = null;
269 |                     }
270 |                     // 打印内容增量（直接输出到 stdout 以避免缓冲）
271 |                     if (chunk.content) {
272 |                         process.stdout.write(chunk.content);
273 |                     }
274 |                     // 处理结束
275 |                     if (chunk.finish_reason) {
276 |                         process.stdout.write('\n\n');
277 |                     }
278 |                 },
279 |                 abortSignal: this.abortController.signal,
280 |             });
281 | 
282 |             if (!response) {
283 |                 this.logger.error('❌ Agent failed to respond');
284 |             }
285 |         } catch (error) {
286 |             // 确保 spinner 被停止
287 |             if (spinner) {
288 |                 spinner.stop();
289 |                 spinner = null;
290 |             }
291 | 
292 |             // 检查是否是取消错误
293 |             if (error instanceof Error && (error.name === 'AbortError' || error.message.includes('abort'))) {
294 |                 // 任务被取消，不打印错误
295 |                 console.log('\n⏹️  Task cancelled');
296 |             } else {
297 |                 const errorMsg = error instanceof Error ? error.message : String(error);
298 |                 this.logger.error(`Error: ${errorMsg}`);
299 |             }
300 |         } finally {
301 |             // 恢复自动换行
302 |             process.stdout.write('\x1B[?7h');
303 | 
304 |             // 清理状态
305 |             this.isProcessingTask = false;
306 |             this.abortController = null;
307 |             this.stopEscListener();
308 |             spinner?.stop();
309 |        
310 |         }
311 |     }
312 | 
313 |     /**
314 |      * 打印欢迎信息
315 |      */
316 |     private printWelcome(): void {
317 |         console.log('\n╔════════════════════════════════════════════════╗');
318 |         console.log('║       AI Agent - Interactive Mode              ║');
319 |         console.log('╚════════════════════════════════════════════════╝');
320 |         console.log(`Session: ${this.agent.context.sessionId}`);
321 |         console.log(`Cache: ${this.agent.context.cacheRoot}`);
322 |         console.log('Type /help for available commands');
323 |         console.log('Press ESC or Ctrl+C to cancel current task');
324 |         console.log('Press Ctrl+C twice to exit');
325 |         console.log('');
326 |     }
327 | 
328 |     /**
329 |      * 优雅退出
330 |      */
331 |     private shutdown(exitCode: number = 0): void {
332 |         this.running = false;
333 |         this.stdinClosed = true;
334 |         this.stopEscListener();
335 |         console.log('\n👋 Goodbye!');
336 |         process.exit(exitCode);
337 |     }
338 | 
339 |     /**
340 |      * 停止 CLI
341 |      */
342 |     stop(): void {
343 |         this.running = false;
344 |         this.stopEscListener();
345 |     }
346 | }
347 | ",
