{
  "filePath": "src/cli/commands/index.ts",
  "content": "1 | /**
2 |  * 命令注册表和路由器
3 |  */
4 | import type { CommandContext, CommandRegistry, CommandHandler } from './types';
5 | import { handler as exitHandler } from './exit';
6 | import { handler as clearHandler } from './clear';
7 | import { handler as historyHandler } from './history';
8 | import { handler as sessionHandler } from './session';
9 | import { handler as helpHandler } from './help';
10 | 
11 | /**
12 |  * 命令注册表
13 |  */
14 | const commands: CommandRegistry = {
15 |     '/exit': exitHandler,
16 |     '/quit': exitHandler,
17 |     '/q': exitHandler,
18 |     '/clear': clearHandler,
19 |     '/history': historyHandler,
20 |     '/session': sessionHandler,
21 |     '/sess': sessionHandler,
22 |     '/help': helpHandler,
23 |     '/?': helpHandler,
24 |     '/h': helpHandler,
25 | };
26 | 
27 | /**
28 |  * 解析命令输入
29 |  */
30 | export function parseCommand(input: string): { command: string; args: string[] } | null {
31 |     if (!input.startsWith('/')) {
32 |         return null;
33 |     }
34 | 
35 |     const parts = input.trim().split(/\s+/);
36 |     const command = parts[0]?.toLowerCase();
37 |     const args = parts.slice(1);
38 | 
39 |     if (!command) {
40 |         return null;
41 |     }
42 | 
43 |     return { command, args };
44 | }
45 | 
46 | /**
47 |  * 执行命令
48 |  */
49 | export async function executeCommand(
50 |     input: string,
51 |     context: CommandContext
52 | ): Promise<boolean> {
53 |     const parsed = parseCommand(input);
54 | 
55 |     if (!parsed) {
56 |         return false;
57 |     }
58 | 
59 |     const { command, args } = parsed;
60 |     const handler = commands[command];
61 | 
62 |     if (!handler) {
63 |         console.log(`❌ Unknown command: ${command}`);
64 |         console.log('Type /help for available commands.\n');
65 |         return true;
66 |     }
67 | 
68 |     await handler.execute(context, args);
69 |     return true;
70 | }
71 | 
72 | /**
73 |  * 获取所有命令（用于自动补全等）
74 |  */
75 | export function getAllCommands(): CommandHandler[] {
76 |     const uniqueHandlers = new Map<string, CommandHandler>();
77 | 
78 |     for (const handler of Object.values(commands)) {
79 |         uniqueHandlers.set(handler.name, handler);
80 |     }
81 | 
82 |     return Array.from(uniqueHandlers.values());
83 | }
84 | 
85 | /**
86 |  * 获取所有命令名称（包括别名）
87 |  */
88 | export function getAllCommandNames(): string[] {
89 |     return Object.keys(commands);
90 | }
91 | 
92 | /**
93 |  * 获取命令补全建议
94 |  */
95 | export function getCommandCompletions(input: string): string[] {
96 |     const allCommands = getAllCommandNames();
97 | 
98 |     if (!input) {
99 |         return allCommands;
100 |     }
101 | 
102 |     return allCommands.filter(cmd => cmd.startsWith(input));
103 | }
104 | ",
