118 | // 工具函数
119 | // =============================================================================
120 | 
121 | function createHeaders(apiKey: string, organization?: string): Headers {
122 |   const headers = new Headers({
123 |     'Content-Type': 'application/json',
124 |     'Authorization': `Bearer ${apiKey}`,
125 |   });
126 |   if (organization) {
127 |     headers.set('OpenAI-Organization', organization);
128 |   }
129 |   return headers;
130 | }
131 | 
132 | function cleanMessage(msg: Message): Record<string, unknown> {
133 |   const cleaned: Record<string, unknown> = {
134 |     role: msg.role,
135 |     content: msg.content,
136 |   };
137 |   if (msg.tool_call_id) {
138 |     cleaned.tool_call_id = msg.tool_call_id;
139 |   }
140 |   if (msg.tool_calls && msg.tool_calls.length > 0) {
141 |     cleaned.tool_calls = msg.tool_calls;
142 |   }
143 |   return cleaned;
144 | }
145 | 
146 | function parseSseLine(line: string): string | null {
147 |   const trimmed = line.trim();
148 |   if (!trimmed || trimmed.startsWith(':')) {
149 |     return null;
150 |   }
151 |   if (trimmed.startsWith('data: ')) {
152 |     return trimmed.slice(6).trim();
153 |   }
154 |   if (trimmed.startsWith('{')) {
155 |     return trimmed;
156 |   }
157 |   return null;
158 | }
159 | 
160 | function isStreamEnd(data: string): boolean {
161 |   return data === '[DONE]';
162 | }
163 | 
164 | function safeJsonParse<T>(data: string): T | null {
165 |   try {
166 |     return JSON.parse(data) as T;
167 |   } catch {
168 |     return null;
169 |   }
170 | }
171 | 
172 | // =============================================================================
173 | // OpenAI Provider
174 | // =============================================================================
175 | 
176 | export interface OpenAIConfig {
177 |   apiKey: string;
178 |   baseURL?: string;
179 |   model?: string;
180 |   maxTokens?: number;
181 |   maxOutputTokens?: number;
182 |   temperature?: number;
183 |   organization?: string;
184 | }
185 | 
186 | export class OpenAIProvider extends LLMProvider {
187 |   readonly baseURL: string;
188 |   readonly organization?: string;
189 |   readonly maxOutputTokens: number;
190 | 
191 |   get model(): string {
192 |     return this.config.model || DEFAULT_MODEL;
193 |   }
194 | 
195 |   get maxTokens(): number {
196 |     return this.config.maxTokens || DEFAULT_MAX_TOKENS;
197 |   }
198 | 
199 |   constructor(config: OpenAIConfig) {
200 |     super({
201 |       apiKey: config.apiKey,
202 |       model: config.model || DEFAULT_MODEL,
203 |       maxTokens: config.maxTokens || DEFAULT_MAX_TOKENS,
204 |       temperature: config.temperature ?? DEFAULT_TEMPERATURE,
205 |     });
206 | 
207 |     this.baseURL = config.baseURL?.replace(/\/$/, '') || DEFAULT_BASE_URL;
208 |     this.organization = config.organization;
209 |     this.maxOutputTokens = config.maxOutputTokens || DEFAULT_MAX_OUTPUT_TOKENS;
210 |   }
211 | 
212 |   async generate(
213 |     messages: Message[],
214 |     options?: LLMOptions
215 |   ): Promise<LLMResponse | null> {
216 |     if (messages.length === 0) {
217 |       return null;
218 |     }
219 | 
220 |     const requestBody = this.buildRequestBody({
221 |       messages,
222 |       model: options?.model,
223 |       maxTokens: options?.max_tokens,
224 |       temperature: options?.temperature,
225 |       tools: options?.tools,
226 |       stream: options?.stream,
227 |     });
228 | 
229 |     if (options?.stream) {
230 |       return await this.generateStream(requestBody, options.streamCallback, options?.abortSignal);
231 |     }
232 | 
233 |     return await this.generateNonStream(requestBody, options?.abortSignal);
234 |   }
235 | 
236 |   private buildRequestBody(params: {
237 |     messages: Message[];
238 |     model?: string;
239 |     maxTokens?: number;
240 |     temperature?: number;
241 |     tools?: LLMOptions['tools'];
242 |     stream?: boolean;
243 |   }): Record<string, unknown> {
244 |     const { messages, model, maxTokens, temperature, tools, stream } = params;
245 | 
246 |     const body: Record<string, unknown> = {
247 |       model: model || this.model,
248 |       messages: messages.map(cleanMessage),
249 |       max_tokens: maxTokens || this.maxOutputTokens,
250 |       temperature: temperature ?? DEFAULT_TEMPERATURE,
251 |       stream: stream ?? false,
252 |     };
253 | 
254 |     if (tools && tools.length > 0) {
255 |       body.tools = tools;
256 |     }
257 | 
258 |     return body;
259 |   }
260 | 
261 |   private async fetchCompletion(body: Record<string, unknown>, abortSignal?: AbortSignal): Promise<Response> {
262 |     const url = `${this.baseURL}${CHAT_COMPLETIONS_PATH}`;
263 | 
264 |     // 打印请求详情用于调试
265 |     console.log('=== API Request ===');
266 |     console.log('URL:', url);
267 |     console.log('Model:', body.model);
268 | 
269 |     const response = await fetch(url, {
270 |       method: 'POST',
271 |       headers: createHeaders(this.config.apiKey || '', this.organization),
272 |       body: JSON.stringify(body),
273 |       signal: abortSignal,
274 |     });
275 | 
276 |     console.log('=== API Response ===');
277 |     console.log('Status:', response.status, response.statusText);
278 | 
279 |     // 检查 HTTP 错误状态，并在非流式模式下抛出异常
280 |     // 流式模式下会在 generateStream 中单独处理
281 |     if (!response.ok) {
282 |       const errorText = await response.text();
283 |       console.error('Error Response Body:', errorText);
284 | 
285 |       // 检查是否是 AbortError
286 |       if (abortSignal?.aborted) {
287 |         const abortError = new LLMError('Request was aborted', 'ABORTED');
288 |         throw abortError;
289 |       }
290 | 
291 |       // 根据状态码创建对应的错误
292 |       throw createErrorFromStatus(response.status, response.statusText, errorText);
293 |     }
294 | 
295 |     return response;
296 |   }
297 | 
298 |   private async generateNonStream(requestBody: Record<string, unknown>, abortSignal?: AbortSignal): Promise<LLMResponse> {
299 |  
300 |     const response = await this.fetchCompletion(requestBody, abortSignal);
301 |   
302 |     if (!response.ok) {
303 |       const errorText = await response.text();
304 |       throw new Error(`API request failed: ${response.status} ${response.statusText} - ${errorText}`);
305 |     }
306 | 
307 |     const data = await response.json() as ChatCompletionResponse;
308 | 
309 |     if (!data.choices || data.choices.length === 0) {
310 |       throw new Error('Empty choices in response');
311 |     }
312 | 
313 |     const choice = data.choices[0];
314 |     const message = choice.message || { role: choice.role || 'assistant', content: choice.content || '' };
315 |     const content = message.content || choice.content || '';
316 |     const finishReason = choice.finish_reason;
317 | 
318 |     if(!content&&!message?.tool_calls?.length){
319 |       throw new Error('Empty content in response');
320 |     }
321 |     console.log(message);
322 |     
323 |     return {
324 |       content: content,
325 |       role: 'assistant',
326 |       type: 'text',
327 |       tool_calls: message.tool_calls?.map(tc => ({
328 |         id: tc.id,
329 |         type: tc.type,
330 |         function: {
331 |           name: tc.function.name,
332 |           arguments: tc.function.arguments,
333 |         },
334 |       })),
335 |       usage: {
336 |         prompt_tokens: data.usage?.prompt_tokens || 0,
337 |         completion_tokens: data.usage?.completion_tokens || 0,
338 |         total_tokens: data.usage?.total_tokens || 0,
339 |       },
340 |       finishReason: finishReason || undefined,
341 |     };
342 |   }
343 | 
344 |   private async generateStream(
345 |     requestBody: Record<string, unknown>,
346 |     streamCallback?: LLMOptions['streamCallback'],
347 |     abortSignal?: AbortSignal
348 |   ): Promise<LLMResponse | null> {
349 | 
350 |     const response = await this.fetchCompletion(requestBody, abortSignal);
351 |     // fetchCompletion 已经处理了 HTTP 错误，这里只需要检查 body
352 | 
353 |     if (!response.body) {
354 |       throw new LLMError('Response body is not readable', 'NO_BODY');
355 |     }
356 | 
357 |     
358 |     const reader = response.body.getReader();
359 |     const decoder = new TextDecoder();
360 | 
361 |     let accumulatedContent = '';
362 |     const toolCallsMap = new Map<number, AccumulatedToolCall>();
363 |     let finishReason: string | undefined;
364 | 
365 |     try {
366 |       await this.processStream(reader, decoder, {
367 |         onContent: (content) => {
368 |           accumulatedContent += content;
369 |           streamCallback?.({ content });
370 |         },
371 |         onToolCall: (toolCall) => {
372 |           const existing = toolCallsMap.get(toolCall.index);
373 |           toolCallsMap.set(toolCall.index, {
374 |             id: existing?.id || toolCall.id || '',
375 |             type: 'function',
376 |             function: {
377 |               name: existing?.function.name || toolCall.function.name || '',
378 |               arguments: (existing?.function.arguments || '') + (toolCall.function.arguments || ''),
379 |             },
380 |           });
381 |         },
382 |         onFinish: (reason) => {
383 |           finishReason = reason;
384 |         },
385 |       });
386 |     } catch (error) {
387 |       console.error('Stream processing error:', error);
388 |       // 重新抛出异常，让上层 Agent 处理
389 |       throw error;
390 |     }
391 | 
392 |     return {
393 |       content: accumulatedContent,
394 |       role: 'assistant',
395 |       type: 'text',
396 |       tool_calls: toolCallsMap.size > 0 ? [...toolCallsMap.values()] : undefined,
397 |       usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
398 |       finishReason,
399 |     };
400 |   }
401 | 
402 |   private async processStream(
403 |     reader: ReadableStreamDefaultReader,
404 |     decoder: typeof TextDecoder.prototype,
405 |     handlers: {
406 |       onContent: (content: string) => void;
407 |       onToolCall: (tc: { index: number; id?: string; type?: string; function: { name?: string; arguments?: string } }) => void;
408 |       onFinish: (reason: string | undefined) => void;
409 |     }
410 |   ): Promise<void> {
411 |     let buffer = '';
412 |     let shouldStop = false;
413 | 
414 |     while (!shouldStop) {
415 |       const { done, value } = await reader.read();
416 |  
417 |       if (done) break;
418 | 
419 |       buffer += decoder.decode(value, { stream: true });
420 |       const lines = buffer.split(/[\r\n]+/);
421 |       buffer = lines.pop() || '';
422 | 
423 |       for (const line of lines) {
424 |         const data = parseSseLine(line);
425 | 
426 |         if (!data) continue;
427 |         
428 |         
429 |         if (isStreamEnd(data)) {
430 |           shouldStop = true;
431 |           break;
432 |         }
433 | 
434 |         const chunk = safeJsonParse<StreamChunkData>(data);
435 |         if (!chunk) continue;
436 | 
437 |         const choice = chunk.choices[0];
438 |         const delta = choice.delta;
439 |         const message = choice.message;
440 | 
441 |         const content = delta?.content || message?.content;
442 |         if (content) {
443 |           handlers.onContent(content);
444 |         }
445 | 
446 |         const toolCallsDelta = delta?.tool_calls;
447 |         if (toolCallsDelta && toolCallsDelta.length > 0) {
448 |           for (const tc of toolCallsDelta) {
449 |             handlers.onToolCall({
450 |               index: tc.index,
451 |               id: tc.id,
452 |               type: tc.type,
453 |               function: {
454 |                 name: tc.function.name,
455 |                 arguments: tc.function.arguments,
456 |               },
457 |             });
458 |           }
459 |         }
460 | 
461 |         const choiceFinishReason = choice.finish_reason;
462 |         if (choiceFinishReason) {
463 |           handlers.onFinish(choiceFinishReason);
464 |         }
465 |       }
466 |     }
467 |   }
468 | }
469 | ",
