{
  "filePath": "src/tool/bash.ts",
  "content": "1 | /**
2 |  * Bash Tool
3 |  *
4 |  * 执行 bash 命令的工具，提供：
5 |  * - 语法验证和解析
6 |  * - 安全分析
7 |  * - 命令执行
8 |  */
9 | 
10 | import { BaseTool, ToolResult } from './base';
11 | import { z } from 'zod';
12 | import { getBashParser } from './bash-parser';
13 | import { getPlatform, execCommandAsync } from '../util/platform-cmd';
14 | 
15 | // =============================================================================
16 | // 模式定义
17 | // =============================================================================
18 | 
19 | const scriptLanguages = ['node', 'python', 'python3'] as const;
20 | type ScriptLanguage = typeof scriptLanguages[number];
21 | 
22 | const schema = z.object({
23 |     command: z.string().min(1).describe('The bash command to run').optional(),
24 |     language: z.enum(scriptLanguages).describe('Inline script language (node/python)').optional(),
25 |     code: z.string().min(1).describe('Inline script to execute').optional(),
26 |     args: z.array(z.string()).describe('Arguments for inline scripts').optional(),
27 |     stdin: z.string().describe('Optional stdin for the command').optional(),
28 | });
29 | 
30 | // =============================================================================
31 | // BashTool 类
32 | // =============================================================================
33 | 
34 | export default class BashTool extends BaseTool<typeof schema> {
35 |     name = 'bash';
36 |     private cwd = process.cwd();
37 | 
38 |     get description(): string {
39 |         return 'Run bash commands, with optional inline node/python scripts';
40 |     }
41 | 
42 |     schema = schema;
43 | 
44 |     /** 命令执行超时时间（毫秒），默认 60 秒 */
45 |     timeout: number = 60000;
46 | 
47 |     /**
48 |      * 执行 bash 命令
49 |      *
50 |      * 错误分类：
51 |      * - 业务错误（参数验证、安全检查）→ return this.fail()
52 |      * - 底层异常（执行失败）→ throw 供 Registry 捕获
53 |      */
54 |     async execute(args: z.infer<typeof this.schema>): Promise<ToolResult> {
55 |         const { command, language, code, args: scriptArgs, stdin } = args;
56 | 
57 |         // === 业务错误：参数验证 ===
58 |         const validationError = this.validateArgs({ command, language, code, args: scriptArgs, stdin });
59 |         if (validationError) {
60 |             return this.fail(validationError, { code: 'VALIDATION_ERROR' });
61 |         }
62 | 
63 |         const hasCode = Boolean(code?.trim());
64 |         const execution = hasCode
65 |             ? { command: this.buildInlineCommand(language as ScriptLanguage, scriptArgs), input: code }
66 |             : { command: command as string, input: stdin };
67 | 
68 |         // === 业务错误：语法检查 ===
69 |         const platform = getPlatform();
70 |         if (platform !== 'windows') {
71 |             const parser = await getBashParser();
72 |             const parseResult = parser.parse(execution.command);
73 |             if (!parseResult.valid) {
74 |                 return this.fail(
75 |                     'Command not executed due to syntax error',
76 |                     { code: 'SYNTAX_ERROR', details: parseResult.error }
77 |                 );
78 |             }
79 |         } else {
80 |             const dangerousPattern = /(^|\s)(format|shutdown|reg\s+delete|rmdir\s+\/s|rd\s+\/s|del\s+\/f)(\s|$)/i;
81 |             if (dangerousPattern.test(execution.command)) {
82 |                 return this.fail(
83 |                     'Command not executed due to safety policy',
84 |                     { code: 'SAFETY_POLICY_VIOLATION' }
85 |                 );
86 |             }
87 |         }
88 | 
89 |         // === 执行命令 ===
90 |         const result = await this.runCommand(execution.command, execution.input);
91 |         return result;
92 |     }
93 | 
94 |     /**
95 |      * 执行 bash 命令
96 |      *
97 |      * 错误分类：
98 |      * - cd 解析失败 → return fail()（业务错误）
99 |      * - 命令执行异常 → throw（底层异常）
100 |      */
101 |     private async runCommand(command: string, input?: string): Promise<ToolResult> {
102 |         // 处理 cd 命令（业务错误）
103 |         const cdError = this.tryHandleCd(command);
104 |         if (cdError) {
105 |             return this.fail(`Command failed: ${cdError}`, { code: 'CD_FAILED' });
106 |         }
107 | 
108 |         const normalizedCommand = this.normalizeCommand(command);
109 | 
110 |         try {
111 |             // === 底层异常：命令执行 ===
112 |             const result = await execCommandAsync(normalizedCommand, {
113 |                 timeout: this.timeout,
114 |                 cwd: this.cwd,
115 |                 input,
116 |             });
117 | 
118 |             if (result.exitCode === 0) {
119 |                 return this.success(
120 |                     { output: result.stdout || 'Command exited successfully' },
121 |                     { truncated: result.stdout.length > 12000 }
122 |                 );
123 |             } else {
124 |                 return this.fail(
125 |                     result.stderr || `Command failed with exit code ${result.exitCode}`,
126 |                     { code: 'COMMAND_FAILED', exitCode: result.exitCode }
127 |                 );
128 |             }
129 |         } catch (error) {
130 |             // 底层异常，让 Registry 统一捕获
131 |             throw new Error(`Failed to execute command: ${error}`);
132 |         }
133 |     }
134 | 
135 |     /**
136 |      * 处理 cd 命令
137 |      * @returns 错误信息，null 表示成功
138 |      */
139 |     private tryHandleCd(command: string): string | null {
140 |         const platform = getPlatform();
141 |         if (/[|;&<>]|\|\||&&/.test(command)) {
142 |             return null; // 复杂命令不做 cd 处理
143 |         }
144 | 
145 |         const cdMatch = command.match(/^\s*cd(?:\s+\/d)?\s+(.+)\s*$/i);
146 |         if (!cdMatch) return null;
147 | 
148 |         const rawTarget = cdMatch[1]?.trim();
149 |         if (!rawTarget) return 'cd target is empty';
150 | 
151 |         const target = rawTarget.replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
152 |         const resolved = platform === 'windows'
153 |             ? require('path').resolve(this.cwd, target.replace(/\//g, '\\'))
154 |             : require('path').resolve(this.cwd, target);
155 | 
156 |         this.cwd = resolved;
157 |         return null;
158 |     }
159 | 
160 |     private normalizeCommand(command: string): string {
161 |         if (getPlatform() !== 'windows') return command;
162 | 
163 |         const timeoutMatch = command.match(/^\s*timeout\s+\/t\s+(\d+)\s*$/i);
164 |         if (timeoutMatch) {
165 |             const seconds = Number(timeoutMatch[1]);
166 |             const safeSeconds = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;
167 |             return `powershell -NoProfile -Command "Start-Sleep -Seconds ${safeSeconds}"`;
168 |         }
169 | 
170 |         const mkdirMatch = command.match(/^\s*mkdir\s+(-p|--parents)\s+(.+)\s*$/i);
171 |         if (mkdirMatch) {
172 |             return `mkdir ${mkdirMatch[2]}`;
173 |         }
174 | 
175 |         const { tokens, quoteTypes } = this.tokenize(command);
176 |         const normalizedTokens = tokens.map((token, i) => {
177 |             const quote = quoteTypes[i];
178 |             const original = quote ? `${quote}${token}${quote}` : token;
179 |             if (!token.includes('/')) return original;
180 |             if (token.startsWith('/')) return original;
181 |             if (token.includes('://')) return original;
182 | 
183 |             const looksLikeProjectPath =
184 |                 token.startsWith('./') ||
185 |                 token.startsWith('../') ||
186 |                 token.startsWith('src/') ||
187 |                 token.startsWith('test/') ||
188 |                 token.startsWith('__tests__/') ||
189 |                 /\.(ts|tsx|js|jsx|json|md|txt|log|env)$/i.test(token) ||
190 |                 token.includes('/src/') ||
191 |                 token.includes('/test/') ||
192 |                 token.includes('/__tests__/');
193 | 
194 |             if (!looksLikeProjectPath) return original;
195 | 
196 |             const replaced = token.replace(/\//g, '\\');
197 |             return quote ? `${quote}${replaced}${quote}` : replaced;
198 |         });
199 | 
200 |         return normalizedTokens.join(' ');
201 |     }
202 | 
203 |     private tokenize(command: string): { tokens: string[]; quoteTypes: Array<'"' | "'" | null> } {
204 |         const tokens: string[] = [];
205 |         const quoteTypes: Array<'"' | "'" | null> = [];
206 |         let current = '';
207 |         let quote: '"' | "'" | null = null;
208 | 
209 |         for (let i = 0; i < command.length; i++) {
210 |             const ch = command[i];
211 |             if ((ch === '"' || ch === "'") && quote === null) {
212 |                 quote = ch as '"' | "'";
213 |                 continue;
214 |             }
215 |             if (quote !== null && ch === quote) {
216 |                 tokens.push(current);
217 |                 quoteTypes.push(quote);
218 |                 current = '';
219 |                 quote = null;
220 |                 continue;
221 |             }
222 |             if (quote === null && /\s/.test(ch)) {
223 |                 if (current.length > 0) {
224 |                     tokens.push(current);
225 |                     quoteTypes.push(null);
226 |                     current = '';
227 |                 }
228 |                 continue;
229 |             }
230 |             current += ch;
231 |         }
232 | 
233 |         if (current.length > 0) {
234 |             tokens.push(current);
235 |             quoteTypes.push(quote);
236 |         }
237 | 
238 |         return { tokens, quoteTypes };
239 |     }
240 | 
241 |     private validateArgs(input: {
242 |         command?: string;
243 |         language?: ScriptLanguage;
244 |         code?: string;
245 |         args?: string[];
246 |         stdin?: string;
247 |     }): string | null {
248 |         const hasCommand = Boolean(input.command?.trim());
249 |         const hasCode = Boolean(input.code?.trim());
250 | 
251 |         if (!hasCommand && !hasCode) {
252 |             return 'missing "command" or "code"';
253 |         }
254 |         if (hasCommand && hasCode) {
255 |             return 'provide either "command" or "code", not both';
256 |         }
257 |         if (hasCode && !input.language) {
258 |             return '"language" is required when using "code"';
259 |         }
260 |         if (!hasCode && input.language) {
261 |             return '"language" is only valid with "code"';
262 |         }
263 |         if (!hasCode && input.args?.length) {
264 |             return '"args" is only valid with "code"';
265 |         }
266 |         if (hasCode && input.stdin !== undefined) {
267 |             return '"stdin" cannot be used with "code"';
268 |         }
269 |         return null;
270 |     }
271 | 
272 |     private buildInlineCommand(language: ScriptLanguage, scriptArgs?: string[]): string {
273 |         const interpreter = this.resolveInterpreter(language);
274 |         const args = scriptArgs ?? [];
275 |         const parts = [interpreter, '-'];
276 |         if (language === 'node' && args.some((arg) => arg.startsWith('-'))) {
277 |             parts.push('--');
278 |         }
279 |         if (args.length > 0) {
280 |             parts.push(...args.map((arg) => this.quoteArg(arg)));
281 |         }
282 |         return parts.join(' ');
283 |     }
284 | 
285 |     private resolveInterpreter(language: ScriptLanguage): string {
286 |         if (language === 'node') return 'node';
287 |         if (language === 'python3') return 'python3';
288 |         return getPlatform() === 'windows' ? 'python' : 'python3';
289 |     }
290 | 
291 |     private quoteArg(arg: string): string {
292 |         const safe = /^[A-Za-z0-9_./:=+-]+$/.test(arg);
293 |         if (safe) return arg;
294 | 
295 |         if (getPlatform() === 'windows') {
296 |             const escaped = arg.replace(/"/g, '\\"');
297 |             return `"${escaped}"`;
298 |         }
299 | 
300 |         const escaped = arg.replace(/'/g, "'\\''");
301 |         return `'${escaped}'`;
302 |     }
303 | }
