423 |     /**
424 |      * 从 JSON Schema 生成示例值
425 |      */
426 |     private static generateExampleValue(schema: unknown, key: string): unknown {
427 |         if (!schema || typeof schema !== 'object') {
428 |             return null;
429 |         }
430 | 
431 |         const s = schema as Record<string, unknown>;
432 | 
433 |         // 如果有 const 值，直接使用
434 |         if ('const' in s) {
435 |             return s.const;
436 |         }
437 | 
438 |         // 如果有示例值，直接使用
439 |         if ('example' in s) {
440 |             return s.example;
441 |         }
442 | 
443 |         // 如果是 enum，使用第一个值
444 |         if ('enum' in s && Array.isArray(s.enum) && s.enum.length > 0) {
445 |             return s.enum[0];
446 |         }
447 | 
448 |         // 根据类型生成示例
449 |         if ('type' in s) {
450 |             switch (s.type) {
451 |                 case 'string':
452 |                     // 根据字段名生成更合理的示例
453 |                     if (key === 'content') return 'Complete task documentation';
454 |                     if (key === 'status') return 'pending';
455 |                     if (key === 'priority') return 'medium';
456 |                     if (key === 'id') return 't_1';
457 |                     if (key === 'op') return 'add';
458 |                     return `example_${key}`;
459 |                 case 'number':
460 |                     return 1;
461 |                 case 'boolean':
462 |                     return true;
463 |                 case 'array':
464 |                     return [];
465 |                 case 'object':
466 |                     // 递归生成嵌套对象的示例
467 |                     if ('properties' in s && s.properties && typeof s.properties === 'object' && !Array.isArray(s.properties)) {
468 |                         const nestedExample: Record<string, unknown> = {};
469 |                         const required = (s.required || []) as string[];
470 |                         for (const [k, v] of Object.entries(s.properties)) {
471 |                             // 只为必需字段或常见字段生成示例
472 |                             if (required.includes(k) || ['content', 'status', 'priority'].includes(k)) {
473 |                                 nestedExample[k] = this.generateExampleValue(v, k);
474 |                             }
475 |                         }
476 |                         return nestedExample;
477 |                     }
478 |                     return {};
479 |                 default:
480 |                     return null;
481 |             }
482 |         }
483 | 
484 |         return null;
485 |     }
