49 | /**
50 |  * 事件总线类
51 |  */
52 | export class EventBus {
53 |   private handlers = new Map<string, Map<string, EventHandler>>();
54 |   private asyncHandlers = new Map<string, Map<string, AsyncEventHandler>>();
55 |   private middlewares = new Map<string, Middleware[]>();
56 |   private globalMiddlewares: Middleware[] = [];
57 |   private options: Required<EventBusOptions>;
58 |   private metrics = new Map<string, EventMetrics>();
59 |   private correlationCounter = 0;
60 | 
61 |   constructor(options: EventBusOptions = {}) {
62 |     this.options = {
63 |       maxListeners: 50,
64 |       enableAsync: true,
65 |       defaultTimeout: 5000,
66 |       enableMetrics: false,
67 |       ...options,
68 |     };
69 |   }
70 | 
71 |   /**
72 |    * 订阅事件（同步处理）
73 |    */
74 |   on<T = any>(event: string, handler: EventHandler<T>, handlerId?: string): Subscription {
75 |     return this.subscribe(event, handler, false, handlerId);
76 |   }
77 | 
78 |   /**
79 |    * 订阅事件（异步处理）
80 |    */
81 |   onAsync<T = any>(event: string, handler: AsyncEventHandler<T>, handlerId?: string): Subscription {
82 |     if (!this.options.enableAsync) {
83 |       throw new Error('Async events are disabled');
84 |     }
85 |     return this.subscribe(event, handler, true, handlerId);
86 |   }
87 | 
88 |   /**
89 |    * 一次性订阅事件
90 |    */
91 |   once<T = any>(event: string, handler: EventHandler<T>): Subscription {
92 |     const subscription = this.on(event, (data: T) => {
93 |       handler(data);
94 |       subscription.unsubscribe();
95 |     });
96 |     return subscription;
97 |   }
98 | 
99 |   /**
100 |    * 一次性订阅事件（异步）
101 |    */
102 |   onceAsync<T = any>(event: string, handler: AsyncEventHandler<T>): Subscription {
103 |     const subscription = this.onAsync(event, async (data: T) => {
104 |       await handler(data);
105 |       subscription.unsubscribe();
106 |     });
107 |     return subscription;
108 |   }
109 | 
110 |   /**
111 |    * 发布事件
112 |    */
113 |   async emit<T = any>(
114 |     event: string,
115 |     data: T,
116 |     metadata: Partial<EventMetadata> = {}
117 |   ): Promise<void> {
118 |     const eventMetrics = this.getOrCreateMetrics(event);
119 |     eventMetrics.totalEvents++;
120 | 
121 |     const context: EventContext<T> = {
122 |       event,
123 |       data,
124 |       metadata: {
125 |         timestamp: Date.now(),
126 |         correlationId: this.generateCorrelationId(),
127 |         ...metadata,
128 |       },
129 |       abort: () => {},
130 |       isAborted: false,
131 |     };
132 | 
133 |     // 设置 abort 函数
134 |     context.abort = () => {
135 |       context.isAborted = true;
136 |     };
137 | 
138 |     // 执行全局中间件
139 |     await this.executeMiddlewares(this.globalMiddlewares, context);
140 | 
141 |     // 执行事件特定中间件
142 |     const eventMiddlewares = this.middlewares.get(event) || [];
143 |     await this.executeMiddlewares(eventMiddlewares, context);
144 | 
145 |     if (context.isAborted) {
146 |       return;
147 |     }
148 | 
149 |     // 执行同步处理器
150 |     const syncHandlers = this.handlers.get(event);
151 |     if (syncHandlers) {
152 |       for (const handler of syncHandlers.values()) {
153 |         try {
154 |           handler(data);
155 |         } catch (error) {
156 |           this.handleError(event, error, context);
157 |         }
158 |       }
159 |     }
160 | 
161 |     // 执行异步处理器
162 |     const asyncHandlers = this.asyncHandlers.get(event);
163 |     if (asyncHandlers && this.options.enableAsync) {
164 |       const promises: Promise<void>[] = [];
165 |       for (const handler of asyncHandlers.values()) {
166 |         promises.push(
167 |           (async () => {
168 |             const startTime = Date.now();
169 |             try {
170 |               await handler(data);
171 |               const executionTime = Date.now() - startTime;
172 |               this.updateMetrics(event, executionTime, false);
173 |             } catch (error) {
174 |               const executionTime = Date.now() - startTime;
175 |               this.updateMetrics(event, executionTime, true);
176 |               this.handleError(event, error, context);
177 |             }
178 |           })()
179 |         );
180 |       }
181 | 
182 |       // 等待所有异步处理器完成（带超时）
183 |       if (promises.length > 0) {
184 |         await Promise.race([
185 |           Promise.all(promises),
186 |           this.createTimeoutPromise(event),
187 |         ]);
188 |       }
189 |     }
190 | 
191 |     eventMetrics.lastEventTime = Date.now();
192 |   }
193 | 
194 |   /**
195 |    * 移除事件监听器
196 |    */
197 |   off(event: string, handlerId: string): boolean {
198 |     let removed = false;
199 | 
200 |     const syncHandlers = this.handlers.get(event);
201 |     if (syncHandlers?.has(handlerId)) {
202 |       syncHandlers.delete(handlerId);
203 |       removed = true;
204 |       if (syncHandlers.size === 0) {
205 |         this.handlers.delete(event);
206 |       }
207 |     }
208 | 
209 |     const asyncHandlers = this.asyncHandlers.get(event);
210 |     if (asyncHandlers?.has(handlerId)) {
211 |       asyncHandlers.delete(handlerId);
212 |       removed = true;
213 |       if (asyncHandlers.size === 0) {
214 |         this.asyncHandlers.delete(event);
215 |       }
216 |     }
217 | 
218 |     return removed;
219 |   }
220 | 
221 |   /**
222 |    * 移除所有事件监听器
223 |    */
224 |   offAll(event?: string): void {
225 |     if (event) {
226 |       this.handlers.delete(event);
227 |       this.asyncHandlers.delete(event);
228 |       this.middlewares.delete(event);
229 |       this.metrics.delete(event);
230 |     } else {
231 |       this.handlers.clear();
232 |       this.asyncHandlers.clear();
233 |       this.middlewares.clear();
234 |       this.metrics.clear();
235 |       this.globalMiddlewares = [];
236 |     }
237 |   }
238 | 
239 |   /**
240 |    * 添加全局中间件
241 |    */
242 |   use(middleware: Middleware): void {
243 |     this.globalMiddlewares.push(middleware);
244 |   }
245 | 
246 |   /**
247 |    * 添加事件特定中间件
248 |    */
249 |   useForEvent(event: string, middleware: Middleware): void {
250 |     const middlewares = this.middlewares.get(event) || [];
251 |     middlewares.push(middleware);
252 |     this.middlewares.set(event, middlewares);
253 |   }
254 | 
255 |   /**
256 |    * 获取事件监听器数量
257 |    */
258 |   listenerCount(event?: string): number {
259 |     if (event) {
260 |       const syncCount = this.handlers.get(event)?.size || 0;
261 |       const asyncCount = this.asyncHandlers.get(event)?.size || 0;
262 |       return syncCount + asyncCount;
263 |     }
264 | 
265 |     let total = 0;
266 |     for (const handlers of this.handlers.values()) {
267 |       total += handlers.size;
268 |     }
269 |     for (const handlers of this.asyncHandlers.values()) {
270 |       total += handlers.size;
271 |     }
272 |     return total;
273 |   }
274 | 
275 |   /**
276 |    * 获取事件列表
277 |    */
278 |   eventNames(): string[] {
279 |     const events = new Set<string>();
280 |     for (const event of this.handlers.keys()) {
281 |       events.add(event);
282 |     }
283 |     for (const event of this.asyncHandlers.keys()) {
284 |       events.add(event);
285 |     }
286 |     for (const event of this.middlewares.keys()) {
287 |       events.add(event);
288 |     }
289 |     return Array.from(events);
290 |   }
291 | 
292 |   /**
293 |    * 获取事件指标
294 |    */
295 |   getMetrics(event?: string): EventMetrics | Map<string, EventMetrics> {
296 |     if (event) {
297 |       return this.metrics.get(event) || this.createEmptyMetrics();
298 |     }
299 |     return new Map(this.metrics);
300 |   }
301 | 
302 |   /**
303 |    * 重置指标
304 |    */
305 |   resetMetrics(event?: string): void {
306 |     if (event) {
307 |       this.metrics.delete(event);
308 |     } else {
309 |       this.metrics.clear();
310 |     }
311 |   }
312 | 
313 |   /**
314 |    * 创建作用域事件总线
315 |    */
316 |   createScopedBus(scope: string): ScopedEventBus {
317 |     return new ScopedEventBus(this, scope);
318 |   }
319 | 
320 |   /**
321 |    * 等待特定事件（Promise 形式）
322 |    */
323 |   waitFor<T = any>(event: string, timeout?: number): Promise<T> {
324 |     return new Promise((resolve, reject) => {
325 |       const timer = timeout
326 |         ? setTimeout(() => {
327 |             subscription.unsubscribe();
328 |             reject(new Error(`Timeout waiting for event: ${event}`));
329 |           }, timeout)
330 |         : undefined;
331 | 
332 |       const subscription = this.once(event, (data: T) => {
333 |         if (timer) clearTimeout(timer);
334 |         resolve(data);
335 |       });
336 |     });
337 |   }
338 | 
339 |   /**
340 |    * 私有方法
341 |    */
342 |   private subscribe<T>(
343 |     event: string,
344 |     handler: EventHandler<T> | AsyncEventHandler<T>,
345 |     isAsync: boolean,
346 |     handlerId?: string
347 |   ): Subscription {
348 |     const id = handlerId || this.generateHandlerId();
349 |     const handlerMap = isAsync ? this.asyncHandlers : this.handlers;
350 | 
351 |     let handlers = handlerMap.get(event);
352 |     if (!handlers) {
353 |       handlers = new Map();
354 |       handlerMap.set(event, handlers);
355 |     }
356 | 
357 |     // 检查监听器数量限制
358 |     if (handlers.size >= this.options.maxListeners) {
359 |       throw new Error(
360 |         `Maximum listeners (${this.options.maxListeners}) exceeded for event: ${event}`
361 |       );
362 |     }
363 | 
364 |     handlers.set(id, handler as any);
365 | 
366 |     // 更新指标
367 |     const metrics = this.getOrCreateMetrics(event);
368 |     metrics.totalHandlers++;
369 | 
370 |     return {
371 |       unsubscribe: () => this.off(event, id),
372 |       event,
373 |       handlerId: id,
374 |     };
375 |   }
376 | 
377 |   private async executeMiddlewares(middlewares: Middleware[], context: EventContext): Promise<void> {
378 |     let index = 0;
379 | 
380 |     const next = async (): Promise<void> => {
381 |       if (index >= middlewares.length || context.isAborted) {
382 |         return;
383 |       }
384 | 
385 |       const middleware = middlewares[index];
386 |       index++;
387 | 
388 |       try {
389 |         await middleware(context, next);
390 |       } catch (error) {
391 |         this.handleError(context.event, error, context);
392 |         throw error;
393 |       }
394 |     };
395 | 
396 |     await next();
397 |   }
398 | 
399 |   private handleError(event: string, error: unknown, context: EventContext): void {
400 |     const metrics = this.getOrCreateMetrics(event);
401 |     metrics.errors++;
402 | 
403 |     // 可以在这里添加错误日志、错误上报等
404 |     console.error(`EventBus error for event "${event}":`, error, context);
405 |   }
406 | 
407 |   private generateCorrelationId(): string {
408 |     return `evt_${Date.now()}_${++this.correlationCounter}`;
409 |   }
410 | 
411 |   private generateHandlerId(): string {
412 |     return `handler_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
413 |   }
414 | 
415 |   private getOrCreateMetrics(event: string): EventMetrics {
416 |     let metrics = this.metrics.get(event);
417 |     if (!metrics) {
418 |       metrics = this.createEmptyMetrics();
419 |       this.metrics.set(event, metrics);
420 |     }
421 |     return metrics;
422 |   }
423 | 
424 |   private createEmptyMetrics(): EventMetrics {
425 |     return {
426 |       totalEvents: 0,
427 |       totalHandlers: 0,
428 |       avgExecutionTime: 0,
429 |       errors: 0,
430 |       lastEventTime: 0,
431 |     };
432 |   }
433 | 
434 |   private updateMetrics(event: string, executionTime: number, isError: boolean): void {
435 |     if (!this.options.enableMetrics) return;
436 | 
437 |     const metrics = this.getOrCreateMetrics(event);
438 |     const totalTime = metrics.avgExecutionTime * (metrics.totalEvents - metrics.errors) + executionTime;
439 |     const validEvents = metrics.totalEvents - metrics.errors + (isError ? 0 : 1);
440 |     
441 |     metrics.avgExecutionTime = validEvents > 0 ? totalTime / validEvents : 0;
442 |     if (isError) {
443 |       metrics.errors++;
444 |     }
445 |   }
446 | 
447 |   private createTimeoutPromise(event: string): Promise<void> {
448 |     return new Promise((_, reject) => {
449 |       setTimeout(() => {
450 |         reject(new Error(`Event "${event}" handler timeout after ${this.options.defaultTimeout}ms`));
451 |       }, this.options.defaultTimeout);
452 |     });
453 |   }
454 | }
