{
  "filePath": "src/util/log.ts",
  "content": "1 | import chalk from 'chalk';
2 | import ora, { Ora } from 'ora';
3 | 
4 | type LogLevel = 'silent' | 'error' | 'warn' | 'info' | 'debug';
5 | 
6 | const LEVEL_ORDER: Record<LogLevel, number> = {
7 |   silent: 0,
8 |   error: 1,
9 |   warn: 2,
10 |   info: 3,
11 |   debug: 4,
12 | };
13 | 
14 | const LEVEL_COLOR: Record<Exclude<LogLevel, 'silent'>, (s: string) => string> = {
15 |   error: (s) => chalk.red(s),
16 |   warn: (s) => chalk.yellow(s),
17 |   info: (s) => chalk.blue(s),
18 |   debug: (s) => chalk.gray(s),
19 | };
20 | 
21 | function now(): string {
22 |   return new Date().toISOString();
23 | }
24 | 
25 | function stringify(input: unknown): string {
26 |   if (typeof input === 'string') return input;
27 |   if (input instanceof Error) {
28 |     const name = input.name || 'Error';
29 |     const msg = input.message || '';
30 |     const stack = input.stack ? `\n${input.stack}` : '';
31 |     return `${name}: ${msg}${stack}`;
32 |   }
33 |   try {
34 |     return JSON.stringify(input, null, 2);
35 |   } catch {
36 |     return String(input);
37 |   }
38 | }
39 | 
40 | function enabled(current: LogLevel, target: LogLevel): boolean {
41 |   return LEVEL_ORDER[current] >= LEVEL_ORDER[target] && current !== 'silent';
42 | }
43 | 
44 | function prefix(level: Exclude<LogLevel, 'silent'>, scope?: string): string {
45 |   const base = `[${now()}] [${level.toUpperCase()}]`;
46 |   const colored = LEVEL_COLOR[level](base);
47 |   return scope ? `${colored} [${scope}]` : colored;
48 | }
49 | 
50 | /**
51 |  * 基于作用域的轻量日志封装
52 |  * 使用场景：为不同子系统/模块创建专属日志器，统一输出风格且保留来源。
53 |  */
54 | class ScopedLogger {
55 |   private readonly scope?: string;
56 |   constructor(scope?: string) {
57 |     this.scope = scope;
58 |   }
59 |   /**
60 |    * 输出一般信息
61 |    * 使用场景：模块初始化、配置加载结果、阶段进入、非异常运行态。
62 |    * @param msg 字符串、对象或 Error，自动格式化
63 |    */
64 |   info(msg: unknown) {
65 |     Log.info(msg, this.scope);
66 |   }
67 |   /**
68 |    * 输出警告信息
69 |    * 使用场景：可恢复异常、降级提示、重试提醒、即将过期/弃用。
70 |    * @param msg 字符串、对象或 Error，自动格式化
71 |    */
72 |   warn(msg: unknown) {
73 |     Log.warn(msg, this.scope);
74 |   }
75 |   /**
76 |    * 输出错误信息
77 |    * 使用场景：失败、异常中断、外部依赖不可用、需要关注的故障。
78 |    * @param msg 字符串、对象或 Error，自动格式化（Error含stack）
79 |    */
80 |   error(msg: unknown) {
81 |     Log.error(msg, this.scope);
82 |   }
83 |   /**
84 |    * 输出成功信息
85 |    * 使用场景：任务完成、构建成功、数据同步完成、阶段性里程碑。
86 |    * @param msg 字符串或对象
87 |    */
88 |   success(msg: unknown) {
89 |     Log.success(msg, this.scope);
90 |   }
91 |   /**
92 |    * 输出调试信息
93 |    * 使用场景：开发诊断、性能测量、参数/上下文细节、仅在debug级别显示。
94 |    * @param msg 字符串或对象
95 |    */
96 |   debug(msg: unknown) {
97 |     Log.debug(msg, this.scope);
98 |   }
99 |   /**
100 |    * 结构化输出对象/JSON
101 |    * 使用场景：接口返回、配置快照、调试上下文、状态采样。
102 |    * @param obj 任意对象（自动JSON格式化）
103 |    * @param label 可选标签，便于快速定位
104 |    */
105 |   json(obj: unknown, label?: string) {
106 |     Log.json(obj, label, this.scope);
107 |   }
108 |   /**
109 |    * 创建并启动进度Spinner
110 |    * 使用场景：长耗时任务（拉取、构建、迁移、上传）；在非TTY自动降级。
111 |    * @param text Spinner文案
112 |    * @returns Ora实例，可用于succeed/fail/stop
113 |    */
114 |   spinner(text: string): Ora {
115 |     return Log.spinner(text, this.scope);
116 |   }
117 | }
118 | 
119 | /**
120 |  * 企业级日志工具：多级日志、作用域、结构化输出、进度Spinner。
121 |  * 级别控制：LOG_LEVEL（silent|error|warn|info|debug）或设置DEBUG=1等价debug级别。
122 |  * 注意：避免输出敏感信息（密钥、令牌、隐私数据）。
123 |  */
124 | class Log {
125 |   private static level: LogLevel = (process.env.LOG_LEVEL as LogLevel) || (process.env.DEBUG ? 'debug' : 'info');
126 | 
127 |   /**
128 |    * 设置全局日志级别
129 |    * 使用场景：测试环境降低噪音、生产环境关闭debug、临时提升诊断粒度。
130 |    * @param level 日志级别
131 |    */
132 |   static setLevel(level: LogLevel) {
133 |     this.level = level;
134 |   }
135 | 
136 |   /**
137 |    * 获取当前全局日志级别
138 |    * 使用场景：运行时判断或输出诊断信息。
139 |    * @returns 当前日志级别
140 |    */
141 |   static getLevel(): LogLevel {
142 |     return this.level;
143 |   }
144 | 
145 |   /**
146 |    * 输出一般信息
147 |    * 使用场景：常规运行信息、关键步骤进入、配置加载结果。
148 |    * @param msg 字符串、对象或 Error，自动格式化
149 |    * @param scope 作用域名称（可选）
150 |    */
151 |   static info(msg: unknown, scope?: string) {
152 |     if (!enabled(this.level, 'info')) return;
153 |     console.log(`${prefix('info', scope)} ${chalk.green(stringify(msg))}`);
154 |   }
155 | 
156 |   /**
157 |    * 输出警告信息
158 |    * 使用场景：可恢复异常、降级路径、超时重试提醒、弃用提示。
159 |    * @param msg 字符串、对象或 Error，自动格式化
160 |    * @param scope 作用域名称（可选）
161 |    */
162 |   static warn(msg: unknown, scope?: string) {
163 |     if (!enabled(this.level, 'warn')) return;
164 |     console.warn(`${prefix('warn', scope)} ${chalk.yellow(stringify(msg))}`);
165 |   }
166 | 
167 |   /**
168 |    * 输出错误信息
169 |    * 使用场景：失败、异常中断、外部依赖不可用、需告警事件。
170 |    * @param msg 字符串、对象或 Error，自动格式化（Error含stack）
171 |    * @param scope 作用域名称（可选）
172 |    */
173 |   static error(msg: unknown, scope?: string) {
174 |     if (!enabled(this.level, 'error')) return;
175 |     console.error(`${prefix('error', scope)} ${chalk.red(stringify(msg))}`);
176 |   }
177 | 
178 |   /**
179 |    * 输出成功信息
180 |    * 使用场景：任务完成、构建成功、数据同步完成、阶段性里程碑。
181 |    * @param msg 字符串或对象
182 |    * @param scope 作用域名称（可选）
183 |    */
184 |   static success(msg: unknown, scope?: string) {
185 |     if (!enabled(this.level, 'info')) return;
186 |     const p = `[${now()}] [SUCCESS]`;
187 |     console.log(`${chalk.green(p)}${scope ? ` [${scope}]` : ''} ${chalk.green(stringify(msg))}`);
188 |   }
189 | 
190 |   /**
191 |    * 输出调试信息（仅在debug级别显示）
192 |    * 使用场景：开发诊断、性能测量、参数与上下文细节。
193 |    * @param msg 字符串或对象
194 |    * @param scope 作用域名称（可选）
195 |    */
196 |   static debug(msg: unknown, scope?: string) {
197 |     if (!enabled(this.level, 'debug')) return;
198 |     console.debug(`${prefix('debug', scope)} ${chalk.gray(stringify(msg))}`);
199 |   }
200 | 
201 |   /**
202 |    * 结构化输出对象/JSON
203 |    * 使用场景：接口返回、配置快照、调试上下文、状态采样。
204 |    * @param obj 任意对象（自动JSON格式化）
205 |    * @param label 可选标签，便于快速定位
206 |    * @param scope 作用域名称（可选）
207 |    */
208 |   static json(obj: unknown, label?: string, scope?: string) {
209 |     const body = stringify(obj);
210 |     const head = label ? `${label}:` : '';
211 |     if (enabled(this.level, 'info')) {
212 |       console.log(`${prefix('info', scope)} ${chalk.white(head)}\n${body}`);
213 |     }
214 |   }
215 | 
216 |   /**
217 |    * 创建指定作用域的日志器
218 |    * 使用场景：为模块/子系统分配独立前缀，便于定位日志来源。
219 |    * @param name 作用域名称
220 |    * @returns ScopedLogger
221 |    */
222 |   static scope(name: string): ScopedLogger {
223 |     return new ScopedLogger(name);
224 |   }
225 | 
226 |   /**
227 |    * 创建并启动进度Spinner
228 |    * 使用场景：长耗时任务（拉取、构建、迁移、上传），TTY环境显示动画。
229 |    * @param text Spinner文案
230 |    * @param scope 作用域名称（可选）
231 |    * @returns Ora实例，可用于succeed/fail/stop
232 |    */
233 |   static spinner(text: string, scope?: string): Ora {
234 |     const full = scope ? `[${scope}] ${text}` : text;
235 |     const isEnabled = process.stdout.isTTY;
236 |     const s = ora({ text: full, isEnabled, spinner: 'dots' }).start();
237 |     return s;
238 |   }
239 | 
240 |   /**
241 |    * 标记Spinner成功结束
242 |    * 使用场景：步骤执行成功后结束进度展示。
243 |    * @param spinner Ora实例
244 |    * @param text 结束文案（可选）
245 |    */
246 |   static spinnerSucceed(spinner: Ora, text?: string) {
247 |     spinner.succeed(text);
248 |   }
249 | 
250 |   /**
251 |    * 标记Spinner失败结束
252 |    * 使用场景：步骤执行失败后结束进度展示。
253 |    * @param spinner Ora实例
254 |    * @param text 结束文案（可选）
255 |    */
256 |   static spinnerFail(spinner: Ora, text?: string) {
257 |     spinner.fail(text);
258 |   }
259 | 
260 |   /**
261 |    * 停止Spinner但不改变状态
262 |    * 使用场景：中断或切换到另一步骤前清理Spinner。
263 |    * @param spinner Ora实例
264 |    */
265 |   static spinnerStop(spinner: Ora) {
266 |     spinner.stop();
267 |   }
268 | }
269 | 
270 | export default Log;
271 | export { ScopedLogger };
