2 |  * ============================================================================
3 |  * Agent Context - 统一的上下文容器
4 |  * ============================================================================
5 |  *
6 |  * 职责：
7 |  * - 集中管理所有运行时上下文
8 |  * - 提供缓存目录、会话 ID、危险操作确认等核心功能
9 |  * - 支持上下文隔离和继承
10 |  */
11 | 
12 | import * as path from 'path';
13 | import * as fs from 'fs/promises';
14 | import { EventEmitter } from 'events';
15 | 
16 | // =============================================================================
17 | // 类型定义
18 | // =============================================================================
19 | 
20 | /**
21 |  * 缓存配置
22 |  */
23 | export interface CacheConfig {
24 |     /** 缓存根目录 */
25 |     rootDir: string;
26 |     /** 工具缓存子目录 */
27 |     toolsDir: string;
28 |     /** LLM 响应缓存 */
29 |     llmCacheDir: string;
30 |     /** 临时文件目录 */
31 |     tempDir: string;
32 |     /** 最大缓存大小 (bytes)，默认 1GB */
33 |     maxCacheSize?: number;
34 |     /** 缓存过期时间 (ms)，默认 24 小时 */
35 |     cacheTtl?: number;
36 | }
37 | 
38 | /**
39 |  * 会话配置
40 |  */
41 | export interface SessionConfig {
42 |     /** 会话 ID */
43 |     sessionId: string;
44 |     /** 用户 ID */
45 |     userId: string;
46 |     /** 会话根目录 */
47 |     sessionDir: string;
48 |     /** 消息历史文件 */
49 |     messagesFile: string;
50 |     /** 状态文件 */
51 |     stateFile: string;
52 |     /** 最大历史消息数 */
53 |     maxHistorySize?: number;
54 |     /** 是否启用自动压缩 */
55 |     enableCompaction?: boolean;
56 | }
57 | 
58 | /**
59 |  * 安全配置
60 |  */
61 | export interface SecurityConfig {
62 |     /** 是否启用危险操作确认 */
63 |     enableConfirmation: boolean;
64 |     /** 危险操作模式: 'prompt' | 'block' | 'allow' */
65 |     dangerousMode: 'prompt' | 'block' | 'allow';
66 |     /** 需要确认的操作类型 */
67 |     dangerousOperations: DangerousOperationDef[];
68 |     /** 白名单路径（不需确认） */
69 |     safePaths?: string[];
70 |     /** 黑名单路径（始终阻止） */
71 |     blockedPaths?: string[];
72 | }
73 | 
74 | /**
75 |  * 危险操作类型
76 |  */
77 | export type DangerousOperation =
78 |     | 'delete_file'
79 |     | 'delete_directory'
80 |     | 'format_disk'
81 |     | 'modify_system_config'
82 |     | 'execute_sudo'
83 |     | 'network_modification'
84 |     | 'modify_critical_file'
85 |     | 'bulk_operation';
86 | 
87 | /**
88 |  * 危险操作定义
89 |  */
90 | export interface DangerousOperationDef {
91 |     type: DangerousOperation;
92 |     patterns: RegExp[];
93 |     description: string;
94 |     confirmationMessage: string;
95 | }
96 | 
97 | /**
98 |  * 操作确认请求
99 |  */
100 | export interface ConfirmationRequest {
101 |     id: string;
102 |     operation: DangerousOperation;
103 |     description: string;
104 |     command: string;
105 |     affectedPath?: string;
106 |     timestamp: Date;
107 |     riskLevel: 'low' | 'medium' | 'high' | 'critical';
108 | }
109 | 
110 | // =============================================================================
111 | // 默认配置
112 | // =============================================================================
113 | 
114 | const DEFAULT_CACHE_CONFIG: Required<CacheConfig> = {
