137 |             confirmationMessage: '你正在执行删除目录操作，这可能是不可逆的',
138 |         },
139 |         {
140 |             type: 'format_disk',
141 |             patterns: [/format\s+/i, /mkfs/i],
142 |             description: '磁盘格式化操作',
