176 |     /**
177 |      * 创建 AgentContext
178 |      */
179 |     constructor(options: {
180 |         cache?: Partial<CacheConfig>;
181 |         session?: Partial<SessionConfig>;
182 |         security?: Partial<SecurityConfig>;
183 |     } = {}) {
184 |         super();
