268 |     /**
269 |      * 读取缓存
270 |      */
271 |     async getCache<T>(key: string): Promise<T | null> {
272 |         const cachePath = this.getCachePath(key);
273 |         try {
274 |             const content = await fs.readFile(cachePath, 'utf-8');
275 |             const data = JSON.parse(content);
276 | 
277 |             // 检查是否过期
278 |             if (data.expiresAt && Date.now() > data.expiresAt) {
279 |                 await fs.unlink(cachePath).catch(() => {});
280 |                 return null;
281 |             }
282 | 
283 |             return data.value as T;
284 |         } catch {
285 |             return null;
286 |         }
287 |     }
