289 |     /**
290 |      * 写入缓存
291 |      */
292 |     async setCache<T>(key: string, value: T, ttlMs?: number): Promise<void> {
293 |         const cachePath = this.getCachePath(key);
294 |         const expiresAt = ttlMs ? Date.now() + ttlMs : Date.now() + this.cacheConfig.cacheTtl!;
295 | 
296 |         await fs.writeFile(
297 |             cachePath,
298 |             JSON.stringify({ value, expiresAt }, null, 2)
299 |         );
300 |     }
