302 |     /**
303 |      * 清理缓存
304 |      */
305 |     async clearCache(reason: string = 'manual'): Promise<void> {
306 |         try {
307 |             await fs.rm(this.sessionCacheDir, { recursive: true, force: true });
308 |             await fs.mkdir(this.sessionCacheDir, { recursive: true });
309 |             this.emit('cache:cleared' as any, reason);
