315 |     /**
316 |      * 获取缓存使用情况
317 |      */
318 |     async getCacheUsage(): Promise<{ size: number; fileCount: number }> {
319 |         let totalSize = 0;
320 |         let fileCount = 0;
321 | 
322 |         const traverse = async (dir: string) => {
323 |             try {
324 |                 const entries = await fs.readdir(dir, { withFileTypes: true });
325 |                 for (const entry of entries) {
326 |                     const fullPath = path.join(dir, entry.name);
327 |                     if (entry.isDirectory()) {
328 |                         await traverse(fullPath);
329 |                     } else {
330 |                         const stats = await fs.stat(fullPath);
331 |                         totalSize += stats.size;
332 |                         fileCount++;
333 |                     }
334 |                 }
335 |             } catch {
336 |                 // 忽略权限错误
337 |             }
338 |         };
339 | 
340 |         await traverse(this.sessionCacheDir);
341 |         return { size: totalSize, fileCount };
342 |     }
