413 |     // =============================================================================
414 |     // 安全管理
415 |     // =============================================================================
416 | 
417 |     /**
418 |      * 检查操作是否危险
419 |      */
420 |     analyzeOperation(command: string, args?: Record<string, unknown>): DangerousOperationDef | null {
421 |         for (const op of this.securityConfig.dangerousOperations) {
422 |             for (const pattern of op.patterns) {
423 |                 if (pattern.test(command)) {
424 |                     // 检查参数中的路径
425 |                     if (args?.filePath) {
426 |                         const filePath = String(args.filePath);
427 |                         if (this.isBlockedPath(filePath)) {
428 |                             return {
429 |                                 type: op.type,
430 |                                 patterns: op.patterns,
431 |                                 description: op.description,
432 |                                 confirmationMessage: `警告：操作目标 ${filePath} 是系统关键路径！`,
433 |                             };
434 |                         }
435 |                     }
436 |                     return op;
437 |                 }
438 |             }
439 |         }
440 |         return null;
441 |     }
442 | 
443 |     /**
444 |      * 检查路径是否被阻止
445 |      */
446 |     private isBlockedPath(filePath: string): boolean {
447 |         const resolved = path.resolve(filePath);
448 |         return this.securityConfig.blockedPaths?.some(p => resolved.startsWith(p)) ?? false;
449 |     }
450 | 
451 |     /**
452 |      * 检查路径是否安全（白名单）
453 |      */
454 |     isSafePath(filePath: string): boolean {
455 |         const resolved = path.resolve(filePath);
456 |         return this.securityConfig.safePaths?.some(p => resolved.includes(p)) ?? false;
457 |     }
458 | 
459 |     /**
460 |      * 请求危险操作确认
461 |      */
462 |     async requestConfirmation(
463 |         operation: DangerousOperation,
464 |         description: string,
465 |         command: string,
466 |         affectedPath?: string
467 |     ): Promise<boolean> {
468 |         if (!this.securityConfig.enableConfirmation) {
469 |             return this.securityConfig.dangerousMode !== 'block';
470 |         }
471 | 
472 |         // 如果是 allow 模式，直接允许
473 |         if (this.securityConfig.dangerousMode === 'allow') {
474 |             return true;
475 |         }
476 | 
477 |         // 如果是 block 模式，直接拒绝
478 |         if (this.securityConfig.dangerousMode === 'block') {
479 |             return false;
480 |         }
481 | 
482 |         // 计算风险等级
483 |         const riskLevel = this.calculateRiskLevel(operation, affectedPath);
484 | 
485 |         const request: ConfirmationRequest = {
486 |             id: this.generateId(),
487 |             operation,
488 |             description,
489 |             command,
490 |             affectedPath,
491 |             timestamp: new Date(),
492 |             riskLevel,
493 |         };
494 | 
495 |         // 发送安全警告事件
496 |         this.emit('security:warning' as any, request);
497 | 
498 |         // 等待用户确认（实际实现需要绑定 UI）
499 |         return new Promise((resolve) => {
500 |             this.confirmationCallbacks.set(request.id, (confirmed) => {
501 |                 this.confirmationCallbacks.delete(request.id);
502 |                 if (confirmed) {
503 |                     this.emit('security:confirmed' as any, request);
504 |                 } else {
505 |                     this.emit('security:denied' as any, request);
506 |                 }
507 |                 resolve(confirmed);
508 |             });
509 | 
510 |             // 超时自动拒绝（30秒）
511 |             setTimeout(() => {
512 |                 if (this.confirmationCallbacks.has(request.id)) {
513 |                     this.confirmationCallbacks.delete(request.id);
514 |                     this.emit('security:denied' as any, request);
515 |                     resolve(false);
516 |                 }
517 |             }, 30000);
518 |         });
519 |     }
520 | 
521 |     /**
522 |      * 处理确认回调（供 UI 调用）
523 |      */
524 |     handleConfirmation(requestId: string, confirmed: boolean): void {
525 |         const callback = this.confirmationCallbacks.get(requestId);
526 |         if (callback) {
527 |             callback(confirmed);
528 |         }
529 |     }
530 | 
531 |     /**
532 |      * 计算风险等级
533 |      */
534 |     private calculateRiskLevel(operation: DangerousOperation, path?: string): 'low' | 'medium' | 'high' | 'critical' {
535 |         const criticalOps: DangerousOperation[] = ['format_disk', 'modify_system_config'];
536 |         const highOps: DangerousOperation[] = ['delete_file', 'delete_directory', 'execute_sudo'];
537 | 
538 |         if (criticalOps.includes(operation)) return 'critical';
539 |         if (highOps.includes(operation)) return 'high';
540 |         if (path && this.isBlockedPath(path)) return 'critical';
541 |         return 'medium';
542 |     }
543 | 
544 |     /**
545 |      * 设置安全模式
546 |      */
547 |     setSecurityMode(mode: 'prompt' | 'block' | 'allow'): void {
548 |         this.securityConfig.dangerousMode = mode;
549 |         console.log(`[Context] Security mode set to: ${mode}`);
550 |     }
551 | 
552 |     /**
553 |      * 添加危险操作模式
554 |      */
555 |     addDangerousOperation(operation: DangerousOperationDef): void {
556 |         this.securityConfig.dangerousOperations.push(operation);
557 |     }
558 | 
559 |     // =============================================================================
560 |     // 工具集成
561 |     // =============================================================================
562 | 
563 |     /**
564 |      * 获取工具上下文
565 |      */
566 |     getToolContext(): {
567 |         sessionId: string;
568 |         sessionDir: string;
569 |         cacheDir: string;
570 |         tempDir: string;
571 |         userId: string;
572 |     } {
573 |         return {
574 |             sessionId: this.sessionConfig.sessionId,
575 |             sessionDir: this.sessionConfig.sessionDir,
576 |             cacheDir: this.sessionCacheDir,
577 |             tempDir: this.tempDir,
578 |             userId: this.sessionConfig.userId,
579 |         };
580 |     }
581 | 
582 |     /**
583 |      * 检查工具是否允许执行
584 |      */
585 |     async canExecuteTool(toolName: string, args: Record<string, unknown>): Promise<{
586 |         allowed: boolean;
587 |         reason?: string;
588 |         requiresConfirmation?: boolean;
589 |     }> {
590 |         // 分析操作是否危险
591 |         const dangerousOp = this.analyzeOperation(toolName, args);
592 | 
593 |         if (dangerousOp) {
594 |             const confirmed = await this.requestConfirmation(
595 |                 dangerousOp.type,
596 |                 dangerousOp.description,
597 |                 `${toolName} ${JSON.stringify(args)}`,
598 |                 args.filePath as string
599 |             );
600 | 
601 |             return {
602 |                 allowed: confirmed,
603 |                 reason: confirmed ? undefined : 'User denied the operation',
604 |                 requiresConfirmation: !confirmed,
605 |             };
606 |         }
607 | 
608 |         return { allowed: true };
609 |     }
