634 |             this.toolsCacheDir,
635 |             this.llmCacheDir,
636 |             this.tempDir,
637 |             this.sessionCacheDir,
638 |         ];
639 | 
640 |         for (const dir of dirs) {
641 |             await fs.mkdir(dir, { recursive: true });
642 |         }
643 |     }
