2 |  * LLM Provider 错误类型定义
3 |  *
4 |  * 错误层次结构：
5 |  * LLMError (基础)
6 |  * ├─ LLMRetryableError (可重试的临时性错误)
7 |  * │   └─ LLMRateLimitError (速率限制)
8 |  * ├─ LLMPermanentError (不可重试的永久性错误)
9 |  * │   ├─ LLMAuthError (认证失败)
10 |  * │   └─ LLMNotFoundError (资源/模型不存在)
11 |  * └─ LLMAbortedError (用户取消)
12 |  */
13 | 
14 | /**
15 |  * LLM 错误基类
16 |  */
17 | export class LLMError extends Error {
18 |   constructor(message: string, public code?: string) {
19 |     super(message);
20 |     this.name = 'LLMError';
21 |     Error.captureStackTrace?.(this, LLMError);
22 |   }
23 | }
24 | 
25 | /**
26 |  * 可重试的临时性错误
27 |  * - 429 Rate Limit
28 |  * - 500, 502, 503, 504 服务器错误
29 |  * - 网络超时、连接失败
30 |  */
31 | export class LLMRetryableError extends LLMError {
32 |   constructor(
33 |     message: string,
34 |     public retryAfter?: number, // 建议重试延迟（毫秒）
35 |     code?: string
36 |   ) {
37 |     super(message, code);
38 |     this.name = 'LLMRetryableError';
39 |   }
40 | 
41 |   /**
42 |    * 获取建议的重试延迟（指数退避）
43 |    */
44 |   getBackoff(retryCount: number): number {
45 |     // 如果有服务器指定的 retry-after，优先使用
46 |     if (this.retryAfter) {
47 |       return this.retryAfter;
48 |     }
49 |     // 否则使用指数退避：2^retryCount * 1000ms
50 |     return Math.pow(2, retryCount) * 1000;
51 |   }
52 | }
53 | 
54 | /**
55 |  * 速率限制错误（429）
56 |  */
57 | export class LLMRateLimitError extends LLMRetryableError {
58 |   constructor(
59 |     message: string,
60 |     public limitType?: 'user' | 'organization' | 'global',
61 |     retryAfter?: number
62 |   ) {
63 |     super(message, retryAfter, 'RATE_LIMIT');
64 |     this.name = 'LLMRateLimitError';
65 |   }
66 | }
67 | 
68 | /**
69 |  * 不可重试的永久性错误
70 |  * - 400 Bad Request
71 |  * - 401 Unauthorized
72 |  * - 404 Not Found
73 |  * - 501 Not Implemented
74 |  */
75 | export class LLMPermanentError extends LLMError {
76 |   constructor(
77 |     message: string,
78 |     public statusCode?: number,
79 |     code?: string
80 |   ) {
81 |     super(message, code);
82 |     this.name = 'LLMPermanentError';
83 |   }
84 | }
85 | 
86 | /**
87 |  * 认证失败错误（401, 403）
88 |  */
89 | export class LLMAuthError extends LLMPermanentError {
90 |   constructor(message: string) {
91 |     super(message, 401, 'AUTH_FAILED');
92 |     this.name = 'LLMAuthError';
93 |   }
94 | }
95 | 
96 | /**
97 |  * 资源/模型不存在错误（404）
98 |  */
99 | export class LLMNotFoundError extends LLMPermanentError {
100 |   constructor(message: string, public resourceType?: 'model' | 'endpoint' | 'resource') {
101 |     super(message, 404, 'NOT_FOUND');
102 |     this.name = 'LLMNotFoundError';
103 |   }
104 | }
105 | 
106 | /**
107 |  * 请求参数错误（400）
