116 | /**
117 |  * 用户取消错误
118 |  */
119 | export class LLMAbortedError extends LLMError {
120 |   constructor(message: string = 'Request was cancelled') {
121 |     super(message, 'ABORTED');
122 |     this.name = 'LLMAbortedError';
123 |   }
124 | }
