126 | /**
127 |  * 工具函数：根据 HTTP 状态码创建对应的错误
128 |  */
129 | export function createErrorFromStatus(
130 |   status: number,
131 |   statusText: string,
132 |   errorText: string
133 | ): LLMError {
134 |   // 解析可能的错误详情
135 |   let details = '';
136 |   try {
137 |     const parsed = JSON.parse(errorText);
138 |     details = parsed.error?.message || errorText;
139 |   } catch {
140 |     details = errorText;
141 |   }
142 | 
143 |   const message = `${status} ${statusText}${details ? ` - ${details}` : ''}`;
144 | 
145 |   switch (status) {
146 |     case 401:
