165 | 
166 |     case 500:
167 |     case 502:
168 |     case 503:
169 |     case 504:
170 |       return new LLMRetryableError(message, undefined, `SERVER_${status}`);
171 | 
172 |     default:
173 |       return new LLMError(message, `HTTP_${status}`);
174 |   }
175 | }
