  "content": "1 | /**
2 |  * EventBus 中间件工具函数
3 |  * 提供常用中间件工厂函数
4 |  */
5 | 
6 | import type { Middleware, EventContext } from './types';
7 | 
8 | /**
9 |  * 创建日志中间件
10 |  */
11 | export function createLoggingMiddleware(source?: string): Middleware {
12 |   return async (context, next) => {
13 |     const startTime = Date.now();
14 |     console.log(`[${source || 'EventBus'}] Event started: ${context.event}`, {
15 |       correlationId: context.metadata.correlationId,
16 |       timestamp: new Date(context.metadata.timestamp).toISOString(),
17 |     });
18 | 
19 |     try {
20 |       await next();
21 |       const duration = Date.now() - startTime;
22 |       console.log(`[${source || 'EventBus'}] Event completed: ${context.event}`, {
23 |         correlationId: context.metadata.correlationId,
24 |         duration: `${duration}ms`,
25 |       });
26 |     } catch (error) {
27 |       const duration = Date.now() - startTime;
28 |       console.error(`[${source || 'EventBus'}] Event failed: ${context.event}`, {
29 |         correlationId: context.metadata.correlationId,
30 |         duration: `${duration}ms`,
31 |         error,
32 |       });
33 |       throw error;
34 |     }
35 |   };
36 | }
37 | 
38 | /**
39 |  * 创建错误处理中间件
40 |  */
41 | export function createErrorHandlingMiddleware(
42 |   onError?: (error: Error, context: EventContext) => void
43 | ): Middleware {
44 |   return async (context, next) => {
45 |     try {
46 |       await next();
47 |     } catch (error) {
48 |       if (onError) {
49 |         onError(error instanceof Error ? error : new Error(String(error)), context);
50 |       }
51 |       throw error;
52 |     }
53 |   };
54 | }
55 | 
56 | /**
57 |  * 创建验证中间件
58 |  */
59 | export function createValidationMiddleware<T>(
60 |   validator: (data: T) => boolean | Promise<boolean>,
61 |   errorMessage = 'Validation failed'
62 | ): Middleware<T> {
63 |   return async (context, next) => {
64 |     const isValid = await validator(context.data);
65 |     if (!isValid) {
66 |       throw new Error(`${errorMessage} for event: ${context.event}`);
67 |     }
68 |     await next();
69 |   };
70 | }
71 | 
72 | /**
73 |  * 创建超时中间件
74 |  */
75 | export function createTimeoutMiddleware(timeoutMs: number): Middleware {
76 |   return async (context, next) => {
77 |     const timeout = setTimeout(() => {
78 |       context.abort();
79 |     }, timeoutMs);
80 | 
81 |     try {
82 |       await next();
83 |     } finally {
84 |       clearTimeout(timeout);
85 |     }
86 |   };
87 | }
88 | 
89 | /**
90 |  * 创建重试中间件
91 |  */
92 | export function createRetryMiddleware(
93 |   maxRetries: number,
94 |   delayMs: number = 1000
95 | ): Middleware {
96 |   return async (context, next) => {
97 |     let attempt = 0;
98 |     let lastError: Error | undefined;
99 | 
100 |     while (attempt <= maxRetries) {
101 |       try {
102 |         await next();
103 |         return; // 成功则返回
104 |       } catch (error) {
105 |         lastError = error instanceof Error ? error : new Error(String(error));
106 |         attempt++;
107 | 
108 |         if (attempt <= maxRetries) {
109 |           // 指数退避
110 |           const backoffMs = delayMs * Math.pow(2, attempt - 1);
111 |           await new Promise(resolve => setTimeout(resolve, backoffMs));
112 |         }
113 |       }
114 |     }
115 | 
116 |     // 重试次数用完，抛出最后一次错误
117 |     if (lastError) {
118 |       throw lastError;
119 |     }
120 |   };
121 | }
122 | ",
