      interface TestEvents {
        'data.process': { data: string };
      }

      const bus = new TypedEventBus<TestEvents>();

      bus.onAsync('data.process', async (data) => {
        expect(typeof data.data).toBe('string');
      });

      await bus.emit('data.process', { data: 'test' });
    });
  });

