      scopedBus.on('event1', vi.fn());
      scopedBus.on('event2', vi.fn());
      scopedBus.on('event3', vi.fn());

      expect(scopedBus.listenerCount()).toBe(3);

      scopedBus.offAll();

      expect(scopedBus.listenerCount()).toBe(0);
    });

