      expect(duration).toBeGreaterThanOrEqual(180);
      expect(duration).toBeLessThan(250);
    });
  });

  describe('11. 设计合理性验证', () => {
    it('11.1 应该遵循单一职责原则', () => {
      const bus = new EventBus();

      // EventBus 职责：管理事件的订阅和发布
      expect(typeof bus.on).toBe('function');
      expect(typeof bus.emit).toBe('function');
      expect(typeof bus.off).toBe('function');
    });

    it('11.2 应该支持开闭原则', () => {
      const bus = new EventBus();

      // 可以扩展功能（通过中间件）
      const extensionMiddleware = async (ctx: any, next: any) => {
        ctx.metadata.extension = true;
        await next();
      };

      bus.use(extensionMiddleware);

      // 无需修改 EventBus 类
      expect(bus.on).toBeDefined();
    });

    it('11.3 应该支持依赖倒置', () => {
      const bus = new EventBus();

      // 依赖抽象接口，而不是具体实现
      const middleware: any = {
        handle: async (ctx: any, next: any) => {
          await next();
        }
      };

      bus.use((ctx: any, next: any) => middleware.handle(ctx, next));
    });

    it('11.4 应该有良好的性能特征', async () => {
      const bus = new EventBus({ enableMetrics: true });
      const handler = vi.fn();

      bus.on('test.performance', handler);

      // 测试 1000 次事件发布
      const start = Date.now();
      for (let i = 0; i < 1000; i++) {
        await bus.emit('test.performance', { index: i });
      }
      const duration = Date.now() - start;

      // 应该在合理时间内完成
      expect(duration).toBeLessThan(2000);

      // 检查指标
      const metrics = bus.getMetrics('test.performance');
      expect(metrics?.totalEvents).toBe(1000);
    });
  });
